{
  "name": "EmpathIA",
  "description": "Una herramienta de transformación de texto impulsada por IA que refina tu escritura añadiendo empatía y otros tonos emocionales para mejorar la comunicación."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ToneOption {
  EMPATHY = 'Empatía',
  PROFESSIONAL = 'Profesional',
  SIMPLIFY = 'Simplificar',
  ASSERTIVE = 'Asertivo'
}

export interface TransformationResult {
  original: string;
  transformed: string;
  appliedTones: ToneOption[];
}

export interface ApiError {
  message: string;
}

import { GoogleGenAI } from "@google/genai";
import { ToneOption } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transformText = async (
  text: string,
  tones: ToneOption[]
): Promise<string> => {
  if (!text.trim()) return "";
  if (tones.length === 0) return text;

  const toneList = tones.join(", ");

  const prompt = `
    Actúa como un experto en comunicación y redacción. Tu tarea es reescribir el siguiente texto aplicando los siguientes filtros o tonos: ${toneList}.

    Reglas:
    1. Mantén el idioma original del texto (detecta automáticamente si es Español, Inglés, etc.).
    2. Preserva el significado y la intención original del mensaje.
    3. Si el tono es "Empatía", asegúrate de que el texto suene comprensivo, cálido y humano, validando los sentimientos del receptor si es necesario.
    4. Devuelve SOLAMENTE el texto reescrito, sin introducciones ni explicaciones adicionales ("Aquí tienes el texto...").

    Texto Original:
    "${text}"
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.7, // Slightly creative to allow for tone shifts
        topK: 40,
        topP: 0.95,
      }
    });

    return response.text || "No se pudo generar el texto.";
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Hubo un error al procesar tu solicitud con Gemini.");
  }
};

import React from 'react';
import { ToneOption } from '../types';
import { Heart, Briefcase, Zap, Shield } from 'lucide-react';

interface OptionButtonProps {
  option: ToneOption;
  isSelected: boolean;
  onClick: () => void;
  disabled?: boolean;
}

const getIcon = (option: ToneOption) => {
  switch (option) {
    case ToneOption.EMPATHY: return <Heart className="w-4 h-4" />;
    case ToneOption.PROFESSIONAL: return <Briefcase className="w-4 h-4" />;
    case ToneOption.SIMPLIFY: return <Zap className="w-4 h-4" />;
    case ToneOption.ASSERTIVE: return <Shield className="w-4 h-4" />;
    default: return null;
  }
};

const getColorClass = (option: ToneOption, isSelected: boolean) => {
  if (!isSelected) return "bg-white text-gray-600 border-gray-200 hover:bg-gray-50";

  switch (option) {
    case ToneOption.EMPATHY: return "bg-rose-100 text-rose-700 border-rose-300 ring-1 ring-rose-300";
    case ToneOption.PROFESSIONAL: return "bg-slate-100 text-slate-700 border-slate-300 ring-1 ring-slate-300";
    case ToneOption.SIMPLIFY: return "bg-amber-100 text-amber-700 border-amber-300 ring-1 ring-amber-300";
    case ToneOption.ASSERTIVE: return "bg-indigo-100 text-indigo-700 border-indigo-300 ring-1 ring-indigo-300";
    default: return "bg-gray-100 text-gray-800";
  }
};

export const OptionButton: React.FC<OptionButtonProps> = ({ option, isSelected, onClick, disabled }) => {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`
        flex items-center gap-2 px-4 py-2 rounded-full border transition-all duration-200
        text-sm font-medium shadow-sm hover:shadow-md active:scale-95
        ${getColorClass(option, isSelected)}
        ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
      `}
    >
      {getIcon(option)}
      <span>{option}</span>
    </button>
  );
};

import React from 'react';
import { Copy, Check, RefreshCw } from 'lucide-react';

interface OutputSectionProps {
  originalText: string;
  transformedText: string;
  isLoading: boolean;
  onRetry: () => void;
}

export const OutputSection: React.FC<OutputSectionProps> = ({ transformedText, isLoading, onRetry }) => {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = async () => {
    if (!transformedText) return;
    try {
      await navigator.clipboard.writeText(transformedText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  if (!transformedText && !isLoading) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 p-8 border-2 border-dashed border-gray-200 rounded-xl bg-gray-50/50">
        <RefreshCw className="w-12 h-12 mb-4 opacity-20" />
        <p className="text-center font-medium">El resultado aparecerá aquí</p>
        <p className="text-sm text-center mt-2 opacity-70">Selecciona una opción y presiona "Transformar"</p>
      </div>
    );
  }

  return (
    <div className="relative flex flex-col h-full bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden transition-all duration-300">
      <div className="flex items-center justify-between px-4 py-3 bg-gray-50 border-b border-gray-100">
        <span className="text-sm font-semibold text-gray-700 flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${isLoading ? 'bg-amber-400 animate-pulse' : 'bg-green-400'}`} />
          {isLoading ? 'Generando...' : 'Resultado'}
        </span>

        {!isLoading && transformedText && (
          <div className="flex gap-2">
             <button
              onClick={onRetry}
              className="p-1.5 text-gray-500 hover:text-indigo-600 hover:bg-indigo-50 rounded-md transition-colors"
              title="Regenerar"
            >
              <RefreshCw className="w-4 h-4" />
            </button>
            <button
              onClick={handleCopy}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-600 bg-white border border-gray-200 rounded-md hover:bg-gray-50 hover:text-gray-900 transition-colors shadow-sm"
            >
              {copied ? <Check className="w-3 h-3 text-green-600" /> : <Copy className="w-3 h-3" />}
              {copied ? 'Copiado' : 'Copiar'}
            </button>
          </div>
        )}
      </div>

      <div className="flex-1 p-6 overflow-y-auto relative">
        {isLoading ? (
          <div className="space-y-3 animate-pulse">
            <div className="h-4 bg-gray-200 rounded w-3/4"></div>
            <div className="h-4 bg-gray-200 rounded w-full"></div>
            <div className="h-4 bg-gray-200 rounded w-5/6"></div>
            <div className="h-4 bg-gray-200 rounded w-4/5"></div>
          </div>
        ) : (
          <div className="prose prose-slate max-w-none">
            <p className="text-gray-800 leading-relaxed whitespace-pre-wrap font-normal text-lg">
              {transformedText}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Sparkles, MessageSquareText, Eraser } from 'lucide-react';
import { ToneOption } from './types';
import { transformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      // For now, let's keep it simple: Single selection or Multi? 
      // User prompt implied simple toggle. Let's allow multi-selection logic but user request focused on 'Empathy'.
      // If we want exclusive selection for simplicity:
      // return [tone]; 

      // If we want toggle behavior:
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  const handleTransform = async () => {
    if (!inputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setOutputText(''); // Clear previous output to show loading state cleanly

    try {
      const result = await transformText(inputText, selectedTones);
      setOutputText(result);
    } catch (err) {
      setError("Ocurrió un error al conectar con la IA. Por favor intenta de nuevo.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setError(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-indigo-50 text-gray-900 font-sans selection:bg-indigo-100 selection:text-indigo-800">

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-indigo-100 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <Sparkles className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-700 to-purple-600">
              EmpathIA
            </h1>
          </div>
          <a href="#" className="text-sm font-medium text-gray-500 hover:text-indigo-600 transition-colors">
            Sobre Nosotros
          </a>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-12">
        <div className="text-center mb-10 max-w-2xl mx-auto">
          <h2 className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight mb-4">
            Mejora tus mensajes con <span className="text-indigo-600">Inteligencia Artificial</span>
          </h2>
          <p className="text-lg text-slate-600">
            Escribe tu texto y selecciona un filtro emocional. Nuestra IA reescribirá tu mensaje manteniendo la intención pero perfeccionando el tono.
          </p>
        </div>

        {/* Options Bar */}
        <div className="flex flex-wrap items-center justify-center gap-3 mb-8">
          <span className="text-sm font-medium text-slate-500 mr-2 uppercase tracking-wider text-xs">Modo:</span>
          {Object.values(ToneOption).map((tone) => (
            <OptionButton
              key={tone}
              option={tone}
              isSelected={selectedTones.includes(tone)}
              onClick={() => toggleTone(tone)}
              disabled={isLoading}
            />
          ))}
        </div>

        {/* Main Interface Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-8 items-stretch h-[600px] lg:h-[500px]">

          {/* Input Section */}
          <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 transition-shadow">
            <div className="flex items-center justify-between px-4 py-3 bg-gray-50 border-b border-gray-100">
              <label htmlFor="input-text" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <MessageSquareText className="w-4 h-4 text-gray-400" />
                Tu Texto Original
              </label>
              <button 
                onClick={handleClear}
                className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors"
                disabled={!inputText}
              >
                <Eraser className="w-3 h-3" />
                Limpiar
              </button>
            </div>
            <textarea
              id="input-text"
              className="flex-1 w-full p-6 resize-none focus:outline-none text-lg text-slate-700 placeholder:text-slate-300 bg-transparent"
              placeholder="Escribe aquí el texto que te gustaría modificar (ej: un correo difícil, un mensaje a un cliente, o una respuesta rápida)..."
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              disabled={isLoading}
            />
             <div className="p-4 border-t border-gray-50 bg-white flex justify-between items-center">
                <span className="text-xs text-gray-400">
                  {inputText.length} caracteres
                </span>
                {/* Mobile-only primary action if needed, though the sticky CTA covers this generally. 
                    Kept here for structure. */}
             </div>
          </div>

          {/* Output Section */}
          <div className="h-full">
            <OutputSection 
              originalText={inputText}
              transformedText={outputText}
              isLoading={isLoading}
              onRetry={handleTransform}
            />
          </div>
        </div>

        {/* Action Bar / Floating CTA */}
        <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-40 w-full max-w-sm px-4">
          <button
            onClick={handleTransform}
            disabled={isLoading || !inputText.trim() || selectedTones.length === 0}
            className={`
              w-full flex items-center justify-center gap-3 py-4 px-8 rounded-2xl shadow-xl shadow-indigo-500/30
              font-bold text-lg text-white transition-all duration-300 transform
              ${isLoading || !inputText.trim() 
                ? 'bg-slate-400 cursor-not-allowed scale-95 opacity-80' 
                : 'bg-indigo-600 hover:bg-indigo-700 hover:scale-105 active:scale-95 bg-gradient-to-r from-indigo-600 to-violet-600'}
            `}
          >
            {isLoading ? (
              <>
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                <span>Transformando...</span>
              </>
            ) : (
              <>
                <Sparkles className="w-5 h-5 fill-indigo-400" />
                <span>Transformar Texto</span>
              </>
            )}
          </button>

          {error && (
            <div className="absolute -top-16 left-0 right-0 mx-4 bg-red-100 text-red-700 px-4 py-2 rounded-lg text-sm text-center border border-red-200 animate-fade-in-up">
              {error}
            </div>
          )}
        </div>

      </main>
    </div>
  );
};

export default App;

