import { GoogleGenAI } from "@google/genai";
import { ToneOption } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transformText = async (
  text: string,
  tones: ToneOption[]
): Promise<string> => {
  if (!text.trim()) return "";
  if (tones.length === 0) return text;

  // Separamos la lógica de parafraseo del resto de los tonos
  const isParaphrase = tones.includes(ToneOption.PARAPHRASE);
  const otherTones = tones.filter(t => t !== ToneOption.PARAPHRASE);

  const toneInstruction = otherTones.length > 0 
    ? `Aplica los siguientes tonos/filtros: ${otherTones.join(", ")}.` 
    : "";

  const structureInstruction = isParaphrase
    ? "MODO PARAFRASEO: Tienes permiso para reestructurar las oraciones para mejorar la fluidez y claridad, pero manteniendo estrictamente el significado original."
    : "MODO EDICIÓN MÍNIMA: NO reescribas todo el texto. Mantén la estructura original casi intacta. Solo haz pequeñas modificaciones o inserta palabras clave para inyectar el tono solicitado (ej. empatía). No cambies el estilo si no es necesario.";

  const prompt = `
    Actúa como un experto en comunicación y redacción.

    ESTA ES TU PRIORIDAD MÁXIMA (Reglas de Oro):
    1. PROTECCIÓN DE DATOS: BAJO NINGUNA CIRCUNSTANCIA modifiques, elimines o traduzcas enlaces (URLs), correos electrónicos, ni nombres propios de productos o marcas específicas.
    2. PALABRAS CLAVE INTOCABLES: Debes mantener exactas las siguientes palabras si aparecen: "TikTok LIVE", "Live", "TikTok", y cualquier link (http...).
    3. NO inventes información.

    Instrucciones de Transformación:
    ${structureInstruction}
    ${toneInstruction}

    Detalles de los Tonos:
    - Si es "Empatía": Agrega calidez, validación y un tono humano. Si NO está activado "Parafrasear", solo suaviza el inicio o final de las frases sin cambiar el núcleo del mensaje.
    - Si es "Profesional": Elimina jerga informal, usa vocabulario preciso.
    - Si es "Simplificar": Hazlo más corto y directo.
    - Si es "Asertivo": Muestra seguridad y firmeza sin ser agresivo.

    Texto Original a procesar:
    "${text}"

    Respuesta (Solo el texto transformado):
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: isParaphrase ? 0.7 : 0.4, // Menor creatividad si no se parafrasea para respetar estructura
        topK: 40,
        topP: 0.95,
      }
    });

    return response.text || "No se pudo generar el texto.";
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Hubo un error al procesar tu solicitud con Gemini.");
  }
};

export enum ToneOption {
  EMPATHY = 'Empatía',
  PARAPHRASE = 'Parafrasear',
  PROFESSIONAL = 'Profesional',
  SIMPLIFY = 'Simplificar',
  ASSERTIVE = 'Asertivo'
}

export enum OutputLanguage {
  AUTO = 'Original (Detectar)',
  ES = 'Español',
  EN = 'Inglés',
  PT = 'Portugués',
  FR = 'Francés',
  // Secondary
  IT = 'Italiano',
  DE = 'Alemán',
  RU = 'Ruso',
  ZH = 'Chino',
  JA = 'Japonés'
}

export interface TransformationResult {
  original: string;
  transformed: string;
  appliedTones: ToneOption[];
  language: OutputLanguage;
}

export interface ApiError {
  message: string;
}

import { GoogleGenAI } from "@google/genai";
import { ToneOption, OutputLanguage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transformText = async (
  text: string,
  tones: ToneOption[],
  targetLanguage: OutputLanguage
): Promise<string> => {
  if (!text.trim()) return "";
  if (tones.length === 0 && targetLanguage === OutputLanguage.AUTO) return text;

  // Separamos la lógica de parafraseo del resto de los tonos
  const isParaphrase = tones.includes(ToneOption.PARAPHRASE);
  const otherTones = tones.filter(t => t !== ToneOption.PARAPHRASE);

  const toneInstruction = otherTones.length > 0 
    ? `Aplica los siguientes tonos/filtros: ${otherTones.join(", ")}.` 
    : "";

  const structureInstruction = isParaphrase
    ? "MODO PARAFRASEO: Tienes permiso para reestructurar las oraciones para mejorar la fluidez y claridad, pero manteniendo estrictamente el significado original."
    : "MODO EDICIÓN MÍNIMA: NO reescribas todo el texto. Mantén la estructura original casi intacta. Solo haz pequeñas modificaciones o inserta palabras clave para inyectar el tono solicitado. No cambies el estilo si no es necesario.";

  const languageInstruction = targetLanguage === OutputLanguage.AUTO
    ? "Mantén el idioma original del texto de entrada."
    : `TRADUCE el resultado final al idioma: ${targetLanguage}.`;

  const prompt = `
    Actúa como un experto en comunicación y redacción multilingüe.

    ESTA ES TU PRIORIDAD MÁXIMA (Reglas de Oro):
    1. PROTECCIÓN DE DATOS: BAJO NINGUNA CIRCUNSTANCIA modifiques, elimines o traduzcas enlaces (URLs), correos electrónicos, ni nombres propios de productos o marcas específicas.
    2. PALABRAS CLAVE INTOCABLES: Debes mantener exactas las siguientes palabras (incluso si traduces el resto del texto): "TikTok LIVE", "Live", "TikTok", y cualquier link (http...). NO las traduzcas (ej: No escribas "TikTok en vivo", mantén "TikTok LIVE").
    3. NO inventes información.

    Instrucciones de Transformación:
    1. ${structureInstruction}
    2. ${toneInstruction}
    3. ${languageInstruction}

    Detalles de los Tonos (aplicar antes o durante la traducción):
    - Si es "Empatía": Agrega calidez, validación y un tono humano. Si NO está activado "Parafrasear", solo suaviza el inicio o final de las frases.
    - Si es "Profesional": Elimina jerga informal, usa vocabulario preciso.
    - Si es "Simplificar": Hazlo más corto y directo.
    - Si es "Asertivo": Muestra seguridad y firmeza sin ser agresivo.

    Texto Original a procesar:
    "${text}"

    Respuesta (Solo el texto transformado en el idioma solicitado):
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: isParaphrase ? 0.7 : 0.4,
        topK: 40,
        topP: 0.95,
      }
    });

    return response.text || "No se pudo generar el texto.";
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Hubo un error al procesar tu solicitud con Gemini.");
  }
};

import React from 'react';
import { OutputLanguage } from '../types';
