import React, { useState } from 'react';
import { Sparkles, MessageSquareText, Eraser } from 'lucide-react';
import { ToneOption, OutputLanguage } from './types';
import { transformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';
import { LanguageSelector } from './components/LanguageSelector';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [selectedLanguage, setSelectedLanguage] = useState<OutputLanguage>(OutputLanguage.AUTO);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  const handleTransform = async () => {
    if (!inputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setOutputText(''); // Clear previous output to show loading state cleanly

    try {
      const result = await transformText(inputText, selectedTones, selectedLanguage);
      setOutputText(result);
    } catch (err) {
      setError("Ocurrió un error al conectar con la IA. Por favor intenta de nuevo.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setError(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-indigo-50 text-gray-900 font-sans selection:bg-indigo-100 selection:text-indigo-800">

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-indigo-100 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <Sparkles className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-700 to-purple-600">
              EmpathIA
            </h1>
          </div>
          <a href="#" className="text-sm font-medium text-gray-500 hover:text-indigo-600 transition-colors">
            Sobre Nosotros
          </a>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-12">
        <div className="text-center mb-10 max-w-2xl mx-auto">
          <h2 className="text-3xl sm:text-4xl font-extrabold text-slate-900 tracking-tight mb-4">
            Mejora tus mensajes con <span className="text-indigo-600">Inteligencia Artificial</span>
          </h2>
          <p className="text-lg text-slate-600">
            Escribe tu texto, selecciona un filtro emocional y el idioma de destino.
          </p>
        </div>

        {/* Options Bar */}
        <div className="flex flex-col md:flex-row items-center justify-center gap-6 mb-8">

          {/* Tones Group */}
          <div className="flex flex-wrap items-center justify-center gap-2">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mr-1 hidden md:inline">Modo:</span>
            {Object.values(ToneOption).map((tone) => (
              <OptionButton
                key={tone}
                option={tone}
                isSelected={selectedTones.includes(tone)}
                onClick={() => toggleTone(tone)}
                disabled={isLoading}
              />
            ))}
          </div>

          <div className="h-8 w-px bg-gray-200 hidden md:block"></div>

          {/* Language Group */}
          <div className="flex items-center gap-2">
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider hidden md:inline">Idioma:</span>
            <LanguageSelector 
              selectedLanguage={selectedLanguage}
              onChange={setSelectedLanguage}
              disabled={isLoading}
            />
          </div>
        </div>

        {/* Main Interface Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-8 items-stretch h-[600px] lg:h-[500px]">

          {/* Input Section */}
          <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 transition-shadow">
            <div className="flex items-center justify-between px-4 py-3 bg-gray-50 border-b border-gray-100">
              <label htmlFor="input-text" className="text-sm font-semibold text-gray-700 flex items-center gap-2">
                <MessageSquareText className="w-4 h-4 text-gray-400" />
                Tu Texto Original
              </label>
              <button 
                onClick={handleClear}
                className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors"
                disabled={!inputText}
              >
                <Eraser className="w-3 h-3" />
                Limpiar
              </button>
            </div>
            <textarea
              id="input-text"
              className="flex-1 w-full p-6 resize-none focus:outline-none text-lg text-slate-700 placeholder:text-slate-300 bg-transparent"
              placeholder="Escribe aquí el texto que te gustaría modificar (ej: un correo difícil, un mensaje a un cliente, o una respuesta rápida)..."
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              disabled={isLoading}
            />
             <div className="p-4 border-t border-gray-50 bg-white flex justify-between items-center">
                <span className="text-xs text-gray-400">
                  {inputText.length} caracteres
                </span>
             </div>
          </div>

          {/* Output Section */}
          <div className="h-full">
            <OutputSection 
              originalText={inputText}
              transformedText={outputText}
              isLoading={isLoading}
              onRetry={handleTransform}
            />
          </div>
        </div>

        {/* Action Bar / Floating CTA */}
        <div className="fixed bottom-6 left-1/2 transform -translate-x-1/2 z-40 w-full max-w-sm px-4">
          <button
            onClick={handleTransform}
            disabled={isLoading || !inputText.trim()}
            className={`
              w-full flex items-center justify-center gap-3 py-4 px-8 rounded-2xl shadow-xl shadow-indigo-500/30
              font-bold text-lg text-white transition-all duration-300 transform
              ${isLoading || !inputText.trim() 
                ? 'bg-slate-400 cursor-not-allowed scale-95 opacity-80' 
                : 'bg-indigo-600 hover:bg-indigo-700 hover:scale-105 active:scale-95 bg-gradient-to-r from-indigo-600 to-violet-600'}
            `}
          >
            {isLoading ? (
              <>
                <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                <span>Transformando...</span>
              </>
            ) : (
              <>
                <Sparkles className="w-5 h-5 fill-indigo-400" />
                <span>Transformar Texto</span>
              </>
            )}
          </button>

          {error && (
            <div className="absolute -top-16 left-0 right-0 mx-4 bg-red-100 text-red-700 px-4 py-2 rounded-lg text-sm text-center border border-red-200 animate-fade-in-up">
              {error}
            </div>
          )}
        </div>

      </main>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { ToneOption, OutputLanguage } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transformText = async (
  text: string,
  tones: ToneOption[],
  targetLanguage: OutputLanguage
): Promise<string> => {
  if (!text.trim()) return "";
  if (tones.length === 0 && targetLanguage === OutputLanguage.AUTO) return text;

  // Separamos la lógica de parafraseo del resto de los tonos
  const isParaphrase = tones.includes(ToneOption.PARAPHRASE);
  const otherTones = tones.filter(t => t !== ToneOption.PARAPHRASE);

  const toneInstruction = otherTones.length > 0 
    ? `Aplica los siguientes tonos/filtros: ${otherTones.join(", ")}.` 
    : "";

  const structureInstruction = isParaphrase
    ? "MODO PARAFRASEO: Tienes permiso para reestructurar las oraciones para mejorar la fluidez y claridad, pero manteniendo estrictamente el significado original."
    : "MODO EDICIÓN MÍNIMA: NO reescribas la estructura central del mensaje. Mantén el núcleo intacto. Tu trabajo es 'envolver' el mensaje original con el tono solicitado (agregando frases al inicio, medio o final).";

  const languageInstruction = targetLanguage === OutputLanguage.AUTO
    ? "Mantén el idioma original del texto de entrada."
    : `TRADUCE el resultado final al idioma: ${targetLanguage}.`;

  const prompt = `
    Actúa como un experto en comunicación y redacción multilingüe.

    ESTA ES TU PRIORIDAD MÁXIMA (Reglas de Oro):
    1. PROTECCIÓN DE DATOS: BAJO NINGUNA CIRCUNSTANCIA modifiques, elimines o traduzcas enlaces (URLs), correos electrónicos, ni nombres propios de productos o marcas específicas.
    2. PALABRAS CLAVE INTOCABLES: Debes mantener exactas las siguientes palabras: "TikTok LIVE", "Live", "TikTok", y cualquier link (http...). NO las traduzcas.
    3. FORMATO VISUAL (CRÍTICO): El resultado NO puede ser un bloque de texto denso. DEBES usar saltos de línea (doble enter) para separar el saludo, las ideas principales y la despedida. Haz que sea visualmente ligero y fácil de leer.

    Instrucciones de Transformación:
    1. ${structureInstruction}
    2. ${toneInstruction}
    3. ${languageInstruction}

    Detalles Específicos de los Tonos:
    - Si es "Empatía": 
        * ESTRATEGIA: Sé extremadamente amable. No solo cambies palabras, AGREGA frases de relleno empático.
        * EJEMPLOS DE RELLENO: Usa frases como "Entiendo perfectamente la situación", "Espero que estés teniendo un día maravilloso", "Muchas gracias por tu paciencia", "Quiero asegurarme de que te sientas cómodo con esto", "Cualquier duda estoy aquí para apoyarte".
        * FORMATO: Separa mucho el texto. Que no se sienta agobiante.
    - Si es "Profesional": Elimina jerga informal, usa vocabulario preciso y mantén distancia respetuosa.
    - Si es "Simplificar": Hazlo más corto y directo, eliminando redundancias.
    - Si es "Asertivo": Muestra seguridad y firmeza sin ser agresivo.

    Texto Original a procesar:
    "${text}"

    Respuesta (Texto transformado, con buena separación de párrafos y palabras clave intactas):
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: isParaphrase ? 0.7 : 0.5, // Un poco más de creatividad para generar frases de relleno empáticas
        topK: 40,
        topP: 0.95,
      }
    });

    return response.text || "No se pudo generar el texto.";
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Hubo un error al procesar tu solicitud con Gemini.");
  }
};

