    console.error("Error calling Gemini API:", error);
    throw new Error("Hubo un error al procesar tu solicitud con Gemini.");
  }
};

export enum ToneOption {
  EMPATHY = 'Empatía',
  PARAPHRASE = 'Parafrasear',
  PROFESSIONAL = 'Profesional',
  SIMPLIFY = 'Simplificar',
  ASSERTIVE = 'Asertivo'
}

export enum MacroType {
  FULL = 'Macro Completo',
  FIRST = 'Primer Mensaje',
  SECOND = 'Segundo Mensaje'
}

export enum OutputLanguage {
  AUTO = 'Original (Detectar)',
  ES = 'Español',
  EN = 'Inglés',
  PT = 'Portugués',
  FR = 'Francés',
  // Secondary
  IT = 'Italiano',
  DE = 'Alemán',
  RU = 'Ruso',
  ZH = 'Chino',
  JA = 'Japonés'
}

export interface TransformationResult {
  original: string;
  transformed: string;
  appliedTones: ToneOption[];
  language: OutputLanguage;
}

export interface ApiError {
  message: string;
}

import React from 'react';
import { MacroType } from '../types';
import { FileText, MessageCircle, Reply } from 'lucide-react';

interface MacroSelectorProps {
  selectedMacro: MacroType;
  onChange: (macro: MacroType) => void;
  disabled?: boolean;
}

export const MacroSelector: React.FC<MacroSelectorProps> = ({ selectedMacro, onChange, disabled }) => {
  return (
    <div className="flex flex-col sm:flex-row gap-2 bg-gray-100/50 p-1.5 rounded-xl border border-gray-200">
      {Object.values(MacroType).map((macro) => {
        const isSelected = selectedMacro === macro;

        let Icon = FileText;
        if (macro === MacroType.FIRST) Icon = MessageCircle;
        if (macro === MacroType.SECOND) Icon = Reply;

        return (
          <button
            key={macro}
            onClick={() => onChange(macro)}
            disabled={disabled}
            className={`
              flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200
              ${isSelected 
                ? 'bg-white text-indigo-700 shadow-sm ring-1 ring-indigo-200' 
                : 'text-gray-600 hover:bg-gray-200/50'
              }
              ${disabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
            `}
          >
            <Icon className={`w-4 h-4 ${isSelected ? 'text-indigo-500' : 'text-gray-400'}`} />
            {macro}
          </button>
        );
      })}
    </div>
  );
};

import React, { useState } from 'react';
import { Sparkles, MessageSquareText, Eraser } from 'lucide-react';
import { ToneOption, OutputLanguage, MacroType } from './types';
import { transformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';
import { LanguageSelector } from './components/LanguageSelector';
import { MacroSelector } from './components/MacroSelector';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [selectedLanguage, setSelectedLanguage] = useState<OutputLanguage>(OutputLanguage.AUTO);
  const [selectedMacro, setSelectedMacro] = useState<MacroType>(MacroType.FULL);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  const handleTransform = async () => {
    if (!inputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setOutputText(''); // Clear previous output to show loading state cleanly

    try {
      const result = await transformText(inputText, selectedTones, selectedLanguage, selectedMacro);
