import { GoogleGenAI } from "@google/genai";
import { ToneOption, OutputLanguage, MacroType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transformText = async (
  text: string,
  tones: ToneOption[],
  targetLanguage: OutputLanguage,
  macroType: MacroType
): Promise<string> => {
  if (!text.trim()) return "";
  if (tones.length === 0 && targetLanguage === OutputLanguage.AUTO && macroType === MacroType.FULL) return text;

  // Separamos la lógica de parafraseo del resto de los tonos
  const isParaphrase = tones.includes(ToneOption.PARAPHRASE);
  const otherTones = tones.filter(t => t !== ToneOption.PARAPHRASE);

  const toneInstruction = otherTones.length > 0 
    ? `Aplica los siguientes tonos/filtros al CUERPO del mensaje: ${otherTones.join(", ")}.` 
    : "";

  const structureInstruction = isParaphrase
    ? "MODO PARAFRASEO: Tienes permiso para reestructurar las oraciones del CUERPO para mejorar la fluidez y claridad."
    : "MODO EDICIÓN MÍNIMA: Mantén la estructura del CUERPO casi idéntica.";

  const languageInstruction = targetLanguage === OutputLanguage.AUTO
    ? "Mantén el idioma original del texto."
    : `TRADUCE TODO el texto (incluido saludos o cabeceras agregadas) al idioma: ${targetLanguage}.`;

  // Lógica específica para los tipos de Macro
  let macroInstruction = "";

  if (macroType === MacroType.FULL) {
    macroInstruction = `
      - TIPO: MACRO COMPLETO.
      - ACCIÓN: El usuario está enviando el mensaje completo. Procesa todo el texto según las reglas de tono.
      - SALUDOS: Si ya existe un saludo estándar ("Hello, Thank you for reaching out..."), mantenlo TÉCNICO y EXACTO (tradúcelo si se pide, pero no le agregues 'salsa' o empatía extra).
    `;
  } else if (macroType === MacroType.FIRST) {
    macroInstruction = `
      - TIPO: PRIMER MENSAJE.
      - ACCIÓN: El texto del usuario es SOLO el cuerpo. Debes ANTEPONER OBLIGATORIAMENTE el siguiente saludo exacto al inicio:
        "Hello,

        Thank you for reaching out to TikTok LIVE. We understand you have an issue with [ISSUE]. We're here to assist you."
      - REGLA DEL SALUDO: 
        1. Reemplaza "[ISSUE]" con el tema principal que deduzcas del texto del usuario (ej: "your subscription", "accessing the live").
        2. NO modifiques el estilo de este saludo. Debe ser estándar.
        3. Traduce este saludo si el targetLanguage lo requiere.
      - REGLA DEL CUERPO: A continuación del saludo, pon el texto del usuario procesado con los tonos seleccionados.
    `;
  } else if (macroType === MacroType.SECOND) {
    macroInstruction = `
      - TIPO: SEGUNDO MENSAJE.
      - ACCIÓN: El texto del usuario es SOLO el cuerpo de una respuesta de seguimiento. Debes ANTEPONER una frase de empatía contextual.
      - FRASE DE APERTURA: Genera algo similar a "We appreciate your patience." o "We know how important it is for you to have this feature activated." basándote en lo que dice el texto.
      - REGLA: Esta frase de apertura debe ser cálida y empática. Luego añade el texto del usuario procesado.
    `;
  }

  const prompt = `
    Actúa como un experto en comunicación para soporte al cliente de TikTok LIVE.

    ESTA ES TU PRIORIDAD MÁXIMA (Reglas de Oro):
    1. PROTECCIÓN DE DATOS: BAJO NINGUNA CIRCUNSTANCIA modifiques, elimines o traduzcas enlaces (URLs), correos electrónicos, ni nombres propios de productos o marcas específicas.
    2. PALABRAS CLAVE INTOCABLES: Debes mantener exactas las siguientes palabras: "TikTok LIVE", "Live", "TikTok", y cualquier link (http...). NO las traduzcas.

    Instrucciones de Construcción del Mensaje (${macroType}):
    ${macroInstruction}

    Instrucciones Generales de Transformación (Aplican al cuerpo del mensaje):
    1. ${structureInstruction}
    2. ${toneInstruction}
    3. ${languageInstruction}

    Detalles Específicos de los Tonos (Para el cuerpo del mensaje):
    - Si es "Empatía": 
        * ESTRATEGIA: Agrega calidez y validación pero SIN EXAGERAR (max +10-20% longitud).
        * ACCIÓN: Suaviza las frases cortantes usando conectores amables.
        * PROHIBIDO: No escribas párrafos enteros de relleno.
    - Si es "Profesional": Elimina jerga informal.

    Texto Original (Input del usuario):
    "${text}"

    Respuesta (Texto final estructurado según el tipo de macro seleccionado):
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.4, // Balanceado para seguir instrucciones estrictas pero permitir fluidez
        topK: 40,
        topP: 0.95,
      }
    });

    return response.text || "No se pudo generar el texto.";
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    throw new Error("Hubo un error al procesar tu solicitud con Gemini.");
  }
};

