import { GoogleGenAI } from "@google/genai";
import { ToneOption, OutputLanguage, MacroType, LengthOption } from "../types";

// Inicialización fuera de la función para no recrear el cliente cada vez
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transformText = async (
  text: string,
  tones: ToneOption[],
  targetLanguage: OutputLanguage,
  macroType: MacroType,
  lengthOption: LengthOption
): Promise<string> => {

  console.log("--- GEMINI SERVICE CALL ---");
  console.log("Input:", { length: text.length, macroType, lengthOption });

  if (!text.trim()) return "";

  // Si no hay cambios solicitados
  if (tones.length === 0 && 
      targetLanguage === OutputLanguage.AUTO && 
      macroType === MacroType.FULL &&
      lengthOption === LengthOption.ORIGINAL) {
    console.log("No transformations required, returning original.");
    return text;
  }

  // Separamos la lógica de parafraseo del resto de los tonos
  const isParaphrase = tones.includes(ToneOption.PARAPHRASE);
  const otherTones = tones.filter(t => t !== ToneOption.PARAPHRASE);

  const toneInstruction = otherTones.length > 0 
    ? `Aplica los siguientes tonos/filtros al CUERPO del mensaje: ${otherTones.join(", ")}.` 
    : "";

  const structureInstruction = isParaphrase
    ? "MODO PARAFRASEO: Tienes permiso para reestructurar las oraciones del CUERPO para mejorar la fluidez y claridad."
    : "MODO EDICIÓN MÍNIMA: Mantén la estructura del CUERPO casi idéntica.";

  const languageInstruction = targetLanguage === OutputLanguage.AUTO
    ? "Mantén el idioma original del texto."
    : `TRADUCE TODO el texto (incluido saludos o cabeceras agregadas) al idioma: ${targetLanguage}.`;

  // Lógica de Longitud
  let lengthInstruction = "";
  switch (lengthOption) {
    case LengthOption.SHORT:
      lengthInstruction = "LONGITUD: Condensa el mensaje. Elimina redundancias y sé directo sin perder educación. Hazlo más CORTO que el original.";
      break;
    case LengthOption.LONG:
      lengthInstruction = "LONGITUD: Expande ligeramente el mensaje. Usa oraciones completas y conectores explicativos para que sea más claro y detallado. Hazlo más LARGO que el original.";
      break;
    case LengthOption.ORIGINAL:
    default:
      lengthInstruction = "LONGITUD: Mantén una longitud similar al texto original.";
      break;
  }

  // Lógica específica para los tipos de Macro
  let macroInstruction = "";

  if (macroType === MacroType.FULL) {
    macroInstruction = `
      - TIPO: MACRO COMPLETO.
      - ACCIÓN: El usuario está enviando el mensaje completo. Procesa todo el texto.
      - SALUDOS: Si ya existe un saludo estándar ("Hello, Thank you for reaching out..."), mantenlo TÉCNICO y EXACTO (tradúcelo si se pide).
    `;
  } else if (macroType === MacroType.FIRST) {
    macroInstruction = `
      - TIPO: PRIMER MENSAJE.
      - ACCIÓN: El texto del usuario es SOLO el cuerpo. ANTEPÓN este saludo exacto:
        "Hello,

        Thank you for reaching out to TikTok LIVE. We understand you have an issue with [ISSUE]. We're here to assist you."
      - REGLA: Reemplaza "[ISSUE]" con el tema del usuario. Traduce si es necesario.
    `;
  } else if (macroType === MacroType.SECOND) {
    macroInstruction = `
      - TIPO: SEGUNDO MENSAJE.
      - ACCIÓN: El texto es respuesta de seguimiento. ANTEPÓN frase de empatía (ej: "We appreciate your patience.").
    `;
  }

  const prompt = `
    Actúa como experto en comunicación para soporte TikTok LIVE.

    REGLAS DE ORO (INVIOLABLES):
    1. PROTECCIÓN DE DATOS: NO toques URLs, emails ni nombres de marcas.
    2. KEYWORDS: Mantén "TikTok LIVE", "Live", "TikTok" exactos.

    Instrucciones Estructurales:
    1. ${macroInstruction}
    2. ${lengthInstruction}

    Instrucciones de Estilo y Idioma:
    1. ${structureInstruction}
    2. ${toneInstruction}
    3. ${languageInstruction}

    Texto Original:
    "${text}"

    Respuesta:
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.4, 
        topK: 40,
        topP: 0.95,
      }
    });

    return response.text || "No se pudo generar el texto.";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(`Error Gemini: ${error.message}`);
  }
};

import React, { useState, useEffect } from 'react';
