import { GoogleGenAI } from "@google/genai";
import { ToneOption, OutputLanguage, MacroType, LengthOption } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

interface TransformParams {
  text: string;
  tones: ToneOption[];
  targetLanguage: OutputLanguage;
  macroType: MacroType;
  lengthOption: LengthOption;
  refinementInstruction?: string; // Nuevo parámetro para refinamiento
  previousOutput?: string;        // Contexto para refinamiento
}

export const streamTransformText = async (
  params: TransformParams,
  onChunk: (text: string) => void
): Promise<string> => {

  const { text, tones, targetLanguage, macroType, lengthOption, refinementInstruction, previousOutput } = params;

  // --- Lógica de Prompt ---
  let prompt = "";

  if (refinementInstruction && previousOutput) {
    // MODO REFINAMIENTO
    prompt = `
      Actúa como experto en comunicación para soporte TikTok LIVE.

      CONTEXTO:
      Anteriormente generaste este texto: "${previousOutput}"

      SOLICITUD DEL USUARIO:
      "${refinementInstruction}"

      TAREA:
      Reescribe el texto anterior aplicando la solicitud del usuario.
      Mantén las reglas de seguridad (No tocar URLs, emails, marcas).
      Mantén el idioma del texto anterior a menos que la solicitud diga lo contrario.
      Devuelve SOLO el texto corregido.
    `;
  } else {
    // MODO TRANSFORMACIÓN ORIGINAL (Lógica existente)
    const isParaphrase = tones.includes(ToneOption.PARAPHRASE);
    const otherTones = tones.filter(t => t !== ToneOption.PARAPHRASE);

    const toneInstruction = otherTones.length > 0 
      ? `Aplica los siguientes tonos/filtros al CUERPO del mensaje: ${otherTones.join(", ")}.` 
      : "";

    const structureInstruction = isParaphrase
      ? "MODO PARAFRASEO: Tienes permiso para reestructurar las oraciones del CUERPO para mejorar la fluidez y claridad."
      : "MODO EDICIÓN MÍNIMA: Mantén la estructura del CUERPO casi idéntica.";

    const languageInstruction = targetLanguage === OutputLanguage.AUTO
      ? "Mantén el idioma original del texto."
      : `TRADUCE TODO el texto (incluido saludos o cierres agregados) al idioma: ${targetLanguage}.`;

    let lengthInstruction = "";
    switch (lengthOption) {
      case LengthOption.SHORT:
        lengthInstruction = "LONGITUD: Condensa el mensaje. Elimina redundancias. Hazlo más CORTO.";
        break;
      case LengthOption.LONG:
        lengthInstruction = "LONGITUD: Expande ligeramente el mensaje con conectores. Hazlo más LARGO.";
        break;
      default:
        lengthInstruction = "LONGITUD: Mantén una longitud similar.";
        break;
    }

    let macroInstruction = "";
    if (macroType === MacroType.FULL) {
      macroInstruction = `
        - TIPO: MACRO COMPLETO.
        - ACCIÓN: Procesa todo el texto.
        - SALUDOS/CIERRES: Mantenlos TÉCNICOS y EXACTOS.
      `;
    } else if (macroType === MacroType.FIRST) {
      macroInstruction = `
        - TIPO: PRIMER MENSAJE.
        - ESTRUCTURA: [SALUDO] + [CUERPO] + [CIERRE]

        1. SALUDO (Elige uno):
           A: "Hi there, Thank you for contacting TikTok LIVE. We understand you're experiencing an issue with your [ISSUE], and we're here to help."
           B: "Hello there, Thank you for reaching out to TikTok LIVE. We're here to assist you. We understand that you need assistance with your [ISSUE]"
           C: "Hi there, Thank you for reaching out to TikTok LIVE. Could you please provide a detailed description of the issue you’re experiencing? This will help us verify and address the problem as quickly as possible."
           * Reemplaza [ISSUE] con el tema.

        2. CUERPO: Texto del usuario procesado.

        3. CIERRE:
           Si NO hay despedida, agrega una:
           i) "If you have any further questions, don't hesitate to get in touch. Thank you and have a great day!"
           ii) "If there’s anything else we can assist you with, please don’t hesitate to let us know. Thank you, and have a wonderful day ahead."
           iii) "If you have any further questions, feel free to let us know. Thank you, and have a wonderful day!"
      `;
    } else if (macroType === MacroType.SECOND) {
      macroInstruction = `
        - TIPO: SEGUNDO MENSAJE.
        - SALUDO (Elige uno y anteponlo):
           A: "Hi there, Thanks for your reply."
           B: "Hello there, We appreciate your swift response."
      `;
    }

    prompt = `
      Actúa como experto en comunicación para soporte TikTok LIVE.

      REGLAS:
      1. NO toques URLs, emails ni nombres de marcas.
      2. Mantén "TikTok LIVE" exacto.

      Instrucciones:
      ${macroInstruction}
      ${lengthInstruction}
      ${structureInstruction}
      ${toneInstruction}
      ${languageInstruction}

      Texto Original: "${text}"

      Respuesta:
    `;
  }

  // --- Ejecución Streaming ---
  try {
    const result = await ai.models.generateContentStream({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        temperature: 0.4, 
        topK: 40,
        topP: 0.95,
      }
    });

    let fullText = '';
    for await (const chunk of result) {
      const chunkText = chunk.text; // Access text property directly
      if (chunkText) {
        fullText += chunkText;
        onChunk(fullText);
      }
    }
    return fullText;

  } catch (error: any) {
    console.error("Gemini Error:", error);
    throw new Error(`Error Gemini: ${error.message}`);
  }
};

