import React, { useEffect, useState } from 'react';
import { PencilLine } from 'lucide-react';

interface VariableManagerProps {
  text: string;
  onUpdateText: (newText: string) => void;
}

interface Variable {
  original: string; // The full string "[ISSUE]"
  key: string;      // "ISSUE"
  value: string;    // Current value
  index: number;    // Position to uniqueness
}

export const VariableManager: React.FC<VariableManagerProps> = ({ text, onUpdateText }) => {
  const [variables, setVariables] = useState<Variable[]>([]);

  // Detect variables on mount or when text changes drastically (though we want to avoid loops)
  // We use a simpler approach: Parse text, find brackets. 
  useEffect(() => {
    const regex = /\[(.*?)\]/g;
    let match;
    const found: Variable[] = [];
    let i = 0;

    // We only want to auto-detect if we haven't already filled them, 
    // but for simplicity in this stateless version, we scan the current text.
    // NOTE: This simple version re-scans. If user types in the textarea, it works.
    while ((match = regex.exec(text)) !== null) {
      found.push({
        original: match[0],
        key: match[1],
        value: '', 
        index: i++
      });
    }

    // Solo actualizamos si la cantidad cambia para evitar re-render loops si el usuario edita el texto manualmente
    // O si es la primera vez
    if (found.length > 0 && variables.length === 0) {
        setVariables(found);
    } else if (found.length === 0 && variables.length > 0) {
        setVariables([]);
    }
  }, [text]);

  const handleValueChange = (index: number, newValue: string) => {
    const variable = variables[index];
    if (!variable) return;

    // Replace first occurrence of this variable in the text
    // This is a naive replacement strategy suitable for simple templates
    const newText = text.replace(variable.original, newValue);
    onUpdateText(newText);

    // Remove the variable from our list since it's replaced
    const newVars = [...variables];
    newVars.splice(index, 1);
    setVariables(newVars);
  };

  if (variables.length === 0) return null;

  return (
    <div className="bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800/30 rounded-lg p-3 mb-4 animate-fade-in">
      <div className="flex items-center gap-2 mb-2 text-amber-800 dark:text-amber-200 text-xs font-bold uppercase tracking-wider">
        <PencilLine className="w-3.5 h-3.5" />
        Variables Detectadas
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {variables.map((v, idx) => (
          <div key={idx} className="flex flex-col gap-1">
            <label className="text-xs text-amber-700 dark:text-amber-300 font-mono">
              {v.original}
            </label>
            <input
              type="text"
              autoFocus={idx === 0}
              placeholder={`Escribe para reemplazar...`}
              className="px-3 py-1.5 text-sm rounded border border-amber-300 dark:border-amber-700 bg-white dark:bg-slate-900 focus:ring-2 focus:ring-amber-500/50 outline-none"
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  handleValueChange(idx, e.currentTarget.value);
                }
              }}
              onBlur={(e) => {
                  if(e.target.value) handleValueChange(idx, e.target.value);
              }}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { diffWords } from 'diff';

interface DiffViewProps {
  original: string;
  modified: string;
}

export const DiffView: React.FC<DiffViewProps> = ({ original, modified }) => {
  if (!original || !modified) return null;

  const diff = diffWords(original, modified);

  return (
    <div className="prose prose-slate dark:prose-invert max-w-none text-lg leading-relaxed whitespace-pre-wrap">
      {diff.map((part, index) => {
        const color = part.added
          ? 'bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-200 decoration-green-500'
          : part.removed
          ? 'bg-red-100 dark:bg-red-900/40 text-red-800 dark:text-red-200 decoration-red-500 line-through decoration-2 opacity-70'
          : 'text-gray-800 dark:text-slate-200';

        return (
          <span key={index} className={`${color} px-0.5 rounded-sm`}>
            {part.value}
          </span>
        );
      })}
    </div>
  );
};

import React, { useState } from 'react';
import { Copy, Check, RefreshCw, GitCompare, Eye, Send, Sparkles, Languages, ArrowDownNarrowWide, Briefcase } from 'lucide-react';
import { DiffView } from './DiffView';
import { VariableManager } from './VariableManager';

interface OutputSectionProps {
  originalText: string;
  transformedText: string;
  isLoading: boolean;
  onRetry: () => void;
  onRefine: (instruction: string) => void;
  onUpdateText: (text: string) => void;
}

type ViewMode = 'final' | 'diff';

export const OutputSection: React.FC<OutputSectionProps> = ({ 
  originalText, 
  transformedText, 
  isLoading, 
  onRetry,
  onRefine,
  onUpdateText
}) => {
  const [copied, setCopied] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('final');
  const [refinementInput, setRefinementInput] = useState('');

  const handleCopy = async () => {
    if (!transformedText) return;
    try {
      await navigator.clipboard.writeText(transformedText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleRefineSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!refinementInput.trim() || isLoading) return;
    onRefine(refinementInput);
    setRefinementInput('');
  };

  const handleQuickAction = (action: string) => {
    onRefine(action);
  };

  if (!transformedText && !isLoading) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 dark:text-slate-500 p-8 border-2 border-dashed border-gray-200 dark:border-slate-700 rounded-2xl bg-gray-50/50 dark:bg-slate-800/30">
        <RefreshCw className="w-12 h-12 mb-4 opacity-20" />
        <p className="text-center font-medium">El resultado aparecerá aquí</p>
        <p className="text-sm text-center mt-2 opacity-70">Selecciona tus opciones y presiona "Transformar"</p>
      </div>
    );
  }

  return (
    <div className="relative flex flex-col h-full bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-gray-200 dark:border-slate-700 overflow-hidden transition-all duration-300">

      {/* Header with Tabs */}
      <div className="flex items-center justify-between px-4 py-2 bg-gray-50 dark:bg-slate-900/50 border-b border-gray-100 dark:border-slate-700">
        <div className="flex bg-white dark:bg-slate-800 p-1 rounded-lg border border-gray-200 dark:border-slate-700">
          <button
            onClick={() => setViewMode('final')}
            className={`flex items-center gap-2 px-3 py-1.5 text-xs font-medium rounded-md transition-all ${viewMode === 'final' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400' : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'}`}
          >
            <Eye className="w-3.5 h-3.5" />
            Vista Final
          </button>
          <button
            onClick={() => setViewMode('diff')}
            className={`flex items-center gap-2 px-3 py-1.5 text-xs font-medium rounded-md transition-all ${viewMode === 'diff' ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400' : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'}`}
          >
            <GitCompare className="w-3.5 h-3.5" />
            Comparar
          </button>
        </div>

        {!isLoading && transformedText && (
          <div className="flex gap-2">
            <button
              onClick={handleCopy}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-gray-600 dark:text-slate-300 bg-white dark:bg-slate-700 border border-gray-200 dark:border-slate-600 rounded-md hover:bg-gray-50 dark:hover:bg-slate-600 transition-colors shadow-sm"
            >
              {copied ? <Check className="w-3 h-3 text-green-600 dark:text-green-400" /> : <Copy className="w-3 h-3" />}
              {copied ? 'Copiado' : 'Copiar'}
            </button>
          </div>
        )}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 overflow-y-auto relative">
        <VariableManager text={transformedText} onUpdateText={onUpdateText} />

        {isLoading && !transformedText ? (
          <div className="space-y-3 animate-pulse">
            <div className="h-4 bg-gray-200 dark:bg-slate-700 rounded w-3/4"></div>
            <div className="h-4 bg-gray-200 dark:bg-slate-700 rounded w-full"></div>
            <div className="h-4 bg-gray-200 dark:bg-slate-700 rounded w-5/6"></div>
          </div>
        ) : (
          viewMode === 'final' ? (
            <div className="prose prose-slate dark:prose-invert max-w-none">
              <p className="text-gray-800 dark:text-slate-200 leading-relaxed whitespace-pre-wrap font-normal text-lg">
                {transformedText}
                {isLoading && <span className="inline-block w-2 h-4 ml-1 bg-indigo-500 animate-pulse"/>}
              </p>
            </div>
          ) : (
            <DiffView original={originalText} modified={transformedText} />
          )
        )}
      </div>

      {/* Footer: Quick Actions & Refinement */}
      {!isLoading && transformedText && (
        <div className="border-t border-gray-100 dark:border-slate-700 bg-gray-50/50 dark:bg-slate-900/30 p-4 space-y-3">

          {/* Quick Actions */}
          <div className="flex flex-wrap gap-2">
             <button onClick={() => handleQuickAction("Hazlo más corto")} className="flex items-center gap-1 px-2 py-1 text-xs bg-white dark:bg-slate-700 border border-gray-200 dark:border-slate-600 rounded hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-300">
                <ArrowDownNarrowWide className="w-3 h-3" /> Más Corto
             </button>
             <button onClick={() => handleQuickAction("Hazlo más formal y profesional")} className="flex items-center gap-1 px-2 py-1 text-xs bg-white dark:bg-slate-700 border border-gray-200 dark:border-slate-600 rounded hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-300">
                <Briefcase className="w-3 h-3" /> Más Formal
             </button>
             <button onClick={() => handleQuickAction("Traducir a Inglés")} className="flex items-center gap-1 px-2 py-1 text-xs bg-white dark:bg-slate-700 border border-gray-200 dark:border-slate-600 rounded hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-300">
                <Languages className="w-3 h-3" /> Inglés
             </button>
