              onChange={(e) => setRefinementInput(e.target.value)}
              placeholder="¿Qué te gustaría cambiar? (ej: 'Cambia el saludo', 'Quita la disculpa')"
              className="w-full pl-4 pr-10 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-600 bg-white dark:bg-slate-800 focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm"
            />
            <button
              type="submit"
              disabled={!refinementInput.trim()}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:bg-gray-400 transition-colors"
            >
              <Send className="w-4 h-4" />
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sparkles, MessageSquareText, Eraser, Moon, Sun, ArrowRight } from 'lucide-react';
import { ToneOption, OutputLanguage, MacroType, LengthOption } from './types';
import { streamTransformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';
import { LanguageSelector } from './components/LanguageSelector';
import { MacroSelector } from './components/MacroSelector';
import { LengthSelector } from './components/LengthSelector';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');

  // State initialization
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [selectedLanguage, setSelectedLanguage] = useState<OutputLanguage>(OutputLanguage.AUTO);
  const [selectedMacro, setSelectedMacro] = useState<MacroType>(MacroType.FULL);
  const [selectedLength, setSelectedLength] = useState<LengthOption>(LengthOption.ORIGINAL);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Handle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  const executeTransformation = async (refinement?: string) => {
    if (!inputText.trim() && !outputText.trim()) return;

    setIsLoading(true);
    setError(null);

    // Si es una transformación nueva, limpiamos el output anterior.
    // Si es un refinamiento, mantenemos el texto mientras se genera el nuevo (o lo limpiamos si queremos efecto visual).
    // Para streaming, mejor limpiar para ver el efecto escribir.
    if (!refinement) {
        setOutputText(''); 
    } else {
        // Guardamos temp el output anterior si lo necesitamos comparar, pero 
        // para la UI de streaming, generalmente se reemplaza.
        // Opcional: Podríamos mostrar un estado de "Refinando..."
        setOutputText(''); 
    }

    try {
      await streamTransformText({
        text: inputText,
        tones: selectedTones,
        targetLanguage: selectedLanguage,
        macroType: selectedMacro,
        lengthOption: selectedLength,
        refinementInstruction: refinement,
        previousOutput: refinement ? outputText : undefined // Pasamos el texto actual como contexto si es refinamiento
      }, (chunk) => {
        setOutputText(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("Error de conexión con IA. Intenta de nuevo.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleTransform = () => executeTransformation();

  const handleRefine = (instruction: string) => {
     // Usamos el outputText actual como base para el refinamiento
     executeTransformation(instruction);
  };

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setError(null);
  };

  return (
    <div className="min-h-screen transition-colors duration-300">

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/90 dark:bg-slate-900/90 backdrop-blur-md border-b border-gray-200 dark:border-slate-800 shadow-sm transition-colors duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-gradient-to-br from-indigo-600 to-violet-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/20">
              <Sparkles className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-700 to-violet-600 dark:from-indigo-400 dark:to-violet-400">
              EmpathIA
            </h1>
          </div>

          <div className="flex items-center gap-4">
            <button
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="p-2 rounded-full text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-slate-800 transition-colors"
              title={isDarkMode ? "Modo Claro" : "Modo Oscuro"}
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-10">

        <div className="flex flex-col gap-6">

          {/* Controls Card */}
          <div className="bg-white dark:bg-slate-800 rounded-2xl p-6 shadow-sm border border-gray-200 dark:border-slate-700 transition-colors duration-300">
            <div className="flex flex-col lg:flex-row gap-6 lg:items-center justify-between">

              <div className="flex flex-col sm:flex-row gap-4 flex-1">
                {/* Macro Selector */}
                <div className="flex flex-col gap-1.5 flex-1">
                  <span className="text-xs font-bold text-gray-400 dark:text-slate-500 uppercase tracking-wider ml-1">Estructura</span>
                  <MacroSelector 
                    selectedMacro={selectedMacro} 
                    onChange={setSelectedMacro} 
                    disabled={isLoading} 
                  />
                </div>

                 {/* Length Selector */}
                 <div className="flex flex-col gap-1.5 w-full sm:w-auto min-w-[200px]">
                  <span className="text-xs font-bold text-gray-400 dark:text-slate-500 uppercase tracking-wider ml-1">Longitud</span>
                  <LengthSelector
                    selectedLength={selectedLength}
                    onChange={setSelectedLength}
                    disabled={isLoading}
                  />
                </div>
              </div>

              {/* Language Selector */}
               <div className="flex flex-col gap-1.5 w-full lg:w-auto">
                  <span className="text-xs font-bold text-gray-400 dark:text-slate-500 uppercase tracking-wider ml-1">Idioma de Salida</span>
                  <LanguageSelector 
                    selectedLanguage={selectedLanguage}
                    onChange={setSelectedLanguage}
                    disabled={isLoading}
                  />
               </div>
            </div>

            <div className="h-px w-full bg-gray-100 dark:bg-slate-700 my-5"></div>

            {/* Tones & Action Row */}
            <div className="flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex flex-col gap-1.5 w-full md:w-auto">
                <span className="text-xs font-bold text-gray-400 dark:text-slate-500 uppercase tracking-wider ml-1 text-center md:text-left">Tonos Emocionales</span>
                <div className="flex flex-wrap justify-center md:justify-start gap-2">
                  {Object.values(ToneOption).map((tone) => (
                    <OptionButton
                      key={tone}
                      option={tone}
                      isSelected={selectedTones.includes(tone)}
                      onClick={() => toggleTone(tone)}
                      disabled={isLoading}
                    />
                  ))}
                </div>
              </div>

              {/* Main Action Button - Now part of the flow */}
              <button
                onClick={handleTransform}
                disabled={isLoading || !inputText.trim()}
                className={`
                  w-full md:w-auto px-8 py-3 rounded-xl flex items-center justify-center gap-2
                  font-bold text-white transition-all duration-300 shadow-lg shadow-indigo-500/20
                  ${isLoading || !inputText.trim() 
                    ? 'bg-slate-400 dark:bg-slate-600 cursor-not-allowed opacity-70' 
                    : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:scale-105 active:scale-95 hover:shadow-indigo-500/40'}
                `}
              >
                {isLoading ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Sparkles className="w-5 h-5" />
                )}
                <span>{isLoading ? 'Procesando...' : 'Transformar Texto'}</span>
                {!isLoading && <ArrowRight className="w-4 h-4 opacity-80" />}
              </button>
            </div>
          </div>

          {/* Main Interface Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-[500px] lg:h-[600px]">

            {/* Input Section */}
            <div className="flex flex-col h-full bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-gray-200 dark:border-slate-700 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-500/40 transition-all duration-300">
              <div className="flex items-center justify-between px-4 py-3 bg-gray-50 dark:bg-slate-900/50 border-b border-gray-100 dark:border-slate-700">
                <label htmlFor="input-text" className="text-sm font-semibold text-gray-700 dark:text-slate-200 flex items-center gap-2">
                  <MessageSquareText className="w-4 h-4 text-gray-400" />
                  Entrada
                </label>
                <button 
                  onClick={handleClear}
                  className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors"
                  disabled={!inputText}
                >
                  <Eraser className="w-3 h-3" />
                  Borrar
                </button>
              </div>
              <textarea
                id="input-text"
                className="flex-1 w-full p-6 resize-none focus:outline-none text-lg text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600 bg-transparent"
                placeholder="Escribe o pega tu texto aquí..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                disabled={isLoading}
              />
               <div className="p-4 border-t border-gray-50 dark:border-slate-700 bg-white dark:bg-slate-800 flex justify-between items-center">
                  <span className="text-xs text-gray-400 dark:text-slate-500">
                    {inputText.length} caracteres
                  </span>
               </div>
            </div>

            {/* Output Section */}
            <div className="h-full">
              <OutputSection 
                originalText={inputText}
                transformedText={outputText}
                isLoading={isLoading}
                onRetry={handleTransform}
                onRefine={handleRefine}
                onUpdateText={setOutputText}
              />
            </div>
          </div>

          {error && (
            <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-300 px-4 py-3 rounded-xl text-center border border-red-100 dark:border-red-900/30 text-sm animate-fade-in">
              {error}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

