              <button
                onClick={handleTransform}
                disabled={isLoading || !inputText.trim()}
                className={`
                  w-full md:w-auto px-8 py-3 rounded-xl flex items-center justify-center gap-2
                  font-bold text-white transition-all duration-300 shadow-lg shadow-indigo-500/20
                  ${isLoading || !inputText.trim() 
                    ? 'bg-slate-400 dark:bg-slate-600 cursor-not-allowed opacity-70' 
                    : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:scale-105 active:scale-95 hover:shadow-indigo-500/40'}
                `}
              >
                {isLoading ? (
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : (
                  <Sparkles className="w-5 h-5" />
                )}
                <span>{isLoading ? 'Procesando...' : 'Transformar Texto'}</span>
                {!isLoading && <ArrowRight className="w-4 h-4 opacity-80" />}
              </button>
            </div>
          </div>

          {/* Main Interface Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-[500px] lg:h-[600px]">

            {/* Input Section */}
            <div className="flex flex-col h-full bg-white dark:bg-slate-800 rounded-2xl shadow-sm border border-gray-200 dark:border-slate-700 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-500/40 transition-all duration-300">
              <div className="flex items-center justify-between px-4 py-3 bg-gray-50 dark:bg-slate-900/50 border-b border-gray-100 dark:border-slate-700">
                <label htmlFor="input-text" className="text-sm font-semibold text-gray-700 dark:text-slate-200 flex items-center gap-2">
                  <MessageSquareText className="w-4 h-4 text-gray-400" />
                  Entrada
                </label>
                <button 
                  onClick={handleClear}
                  className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors"
                  disabled={!inputText}
                >
                  <Eraser className="w-3 h-3" />
                  Borrar
                </button>
              </div>
              <textarea
                id="input-text"
                className="flex-1 w-full p-6 resize-none focus:outline-none text-lg text-slate-700 dark:text-slate-200 placeholder:text-slate-300 dark:placeholder:text-slate-600 bg-transparent"
                placeholder="Escribe o pega el cuerpo de tu respuesta aquí..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                disabled={isLoading}
              />
               <div className="p-4 border-t border-gray-50 dark:border-slate-700 bg-white dark:bg-slate-800 flex justify-between items-center">
                  <span className="text-xs text-gray-400 dark:text-slate-500">
                    {inputText.length} caracteres
                  </span>
               </div>
            </div>

            {/* Output Section */}
            <div className="h-full">
              <OutputSection 
                originalText={inputText}
                transformedText={outputText}
                isLoading={isLoading}
                onRetry={handleTransform}
                onRefine={handleRefine}
                onUpdateText={setOutputText}
              />
            </div>
          </div>

          {error && (
            <div className="bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-300 px-4 py-3 rounded-xl text-center border border-red-100 dark:border-red-900/30 text-sm animate-fade-in">
              {error}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

