) => {
  return streamTransformText({ text, tones, targetLanguage, macroType, lengthOption, perspective }, () => {});
};

import React, { useState, useEffect } from 'react';
import { Sparkles, MessageSquareText, Eraser, Moon, Sun, ArrowRight, PenLine } from 'lucide-react';
