      {getIcon(option)}
      <span>{option}</span>
    </button>
  );
};

import React, { useState } from 'react';
import { Copy, Check, GitCompare, Eye, Send, Sparkles, Languages, ArrowDownNarrowWide, Briefcase, Wand2 } from 'lucide-react';
import { DiffView } from './DiffView';
import { VariableManager } from './VariableManager';

interface OutputSectionProps {
  originalText: string;
  transformedText: string;
  isLoading: boolean;
  onRetry: () => void;
  onRefine: (instruction: string) => void;
  onUpdateText: (text: string) => void;
}

type ViewMode = 'final' | 'diff';

export const OutputSection: React.FC<OutputSectionProps> = ({ 
  originalText, 
  transformedText, 
  isLoading, 
  onRetry,
  onRefine,
  onUpdateText
}) => {
  const [copied, setCopied] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('final');
  const [refinementInput, setRefinementInput] = useState('');

  const handleCopy = async () => {
    if (!transformedText) return;
    try {
      await navigator.clipboard.writeText(transformedText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleRefineSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!refinementInput.trim() || isLoading) return;
    onRefine(refinementInput);
    setRefinementInput('');
  };

  const handleQuickAction = (action: string) => {
    onRefine(action);
  };

  if (!transformedText && !isLoading) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 dark:text-slate-500 p-8">
        <div className="w-20 h-20 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6 animate-pulse">
            <Wand2 className="w-8 h-8 text-indigo-200 dark:text-slate-600" />
        </div>
