                <textarea
                    className="flex-1 w-full bg-transparent border-none outline-none resize-none text-gray-700 dark:text-slate-200 leading-relaxed font-normal text-[15px] sm:text-base selection:bg-indigo-100 selection:text-indigo-900 placeholder:text-gray-400 p-0"
