                <Briefcase className="w-3 h-3" /> Más Formal
             </button>
             <button onClick={() => handleQuickAction("Traducir a Inglés")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <Languages className="w-3 h-3" /> Inglés
             </button>
          </div>

          {/* Chat Input */}
          <form onSubmit={handleRefineSubmit} className="relative group">
            <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/20 to-violet-500/20 rounded-xl blur opacity-0 group-focus-within:opacity-100 transition-opacity duration-500"></div>
            <input
              type="text"
              value={refinementInput}
              onChange={(e) => setRefinementInput(e.target.value)}
              placeholder="✨ ¿Quieres ajustar algo? (Ej: 'Quita la disculpa', 'Hazlo más amable')"
              className="relative w-full pl-4 pr-10 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-600 bg-white dark:bg-slate-800 focus:border-indigo-400 dark:focus:border-indigo-500 outline-none transition-all shadow-sm focus:shadow-md dark:text-slate-200 placeholder:text-gray-400"
            />
            <button
              type="submit"
              disabled={!refinementInput.trim()}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-gradient-to-tr from-indigo-600 to-violet-600 text-white rounded-lg hover:shadow-lg disabled:opacity-50 disabled:shadow-none transition-all duration-200 hover:scale-105 active:scale-95"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

