              title="Autocorregir Ortografía y Gramática con IA"
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border bg-white dark:bg-slate-800 text-amber-600 dark:text-amber-400 border-gray-200 dark:border-slate-600 hover:border-amber-300 dark:hover:border-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 transition-all duration-200"
            >
               <SpellCheck2 className="w-3.5 h-3.5" />
               <span className="hidden sm:inline">Corregir</span>
            </button>

            <button
              onClick={handleCopy}
              className={`
                flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border transition-all duration-200
                ${copied 
                    ? 'bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-400 border-green-200 dark:border-green-800' 
                    : 'bg-white dark:bg-slate-800 text-gray-600 dark:text-slate-300 border-gray-200 dark:border-slate-600 hover:border-indigo-300 dark:hover:border-indigo-500 hover:text-indigo-600'
                }
              `}
            >
              {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
              {copied ? 'Copiado' : 'Copiar'}
            </button>
          </div>
        )}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 overflow-y-auto relative bg-white/40 dark:bg-transparent">
        <VariableManager text={transformedText} onUpdateText={onUpdateText} />

        {isLoading && !transformedText ? (
          <div className="space-y-4 animate-pulse mt-4">
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-3/4"></div>
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-full"></div>
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-5/6"></div>
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-2/3"></div>
          </div>
        ) : (
          viewMode === 'final' ? (
            <div className="h-full flex flex-col animate-fade-in">
                {isLoading && <div className="text-xs text-indigo-500 mb-2 animate-pulse font-medium">✨ Generando...</div>}
                <textarea
                    className="flex-1 w-full bg-transparent border-none outline-none resize-none text-gray-700 dark:text-slate-200 leading-relaxed font-normal text-[15px] sm:text-base selection:bg-indigo-100 selection:text-indigo-900 placeholder:text-gray-400 p-0"
                    value={transformedText}
                    onChange={(e) => onUpdateText(e.target.value)}
                    spellCheck={true}
                    lang="es" 
                    placeholder="El resultado aparecerá aquí..."
                />
            </div>
          ) : (
            <DiffView original={originalText} modified={transformedText} />
          )
        )}
      </div>

      {/* Footer: Quick Actions & Refinement */}
      {!isLoading && transformedText && (
        <div className="border-t border-gray-100 dark:border-slate-700 bg-gray-50/80 dark:bg-slate-900/40 p-3 space-y-3 backdrop-blur-md">

          {/* Quick Actions Chips */}
          <div className="flex flex-wrap gap-2 justify-center sm:justify-start">
             <button onClick={() => handleQuickAction("Hazlo más corto")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <ArrowDownNarrowWide className="w-3 h-3" /> Más Corto
             </button>
             <button onClick={() => handleQuickAction("Hazlo más formal y profesional")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <Briefcase className="w-3 h-3" /> Más Formal
             </button>
             <button onClick={() => handleQuickAction("Traducir a Inglés")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <Languages className="w-3 h-3" /> Inglés
             </button>
          </div>

          {/* Chat Input */}
          <form onSubmit={handleRefineSubmit} className="relative group">
            <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/20 to-violet-500/20 rounded-xl blur opacity-0 group-focus-within:opacity-100 transition-opacity duration-500"></div>
            <input
              type="text"
              value={refinementInput}
              onChange={(e) => setRefinementInput(e.target.value)}
              placeholder="✨ ¿Quieres ajustar algo? (Ej: 'Quita la disculpa', 'Hazlo más amable')"
              className="relative w-full pl-4 pr-10 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-600 bg-white dark:bg-slate-800 focus:border-indigo-400 dark:focus:border-indigo-500 outline-none transition-all shadow-sm focus:shadow-md dark:text-slate-200 placeholder:text-gray-400"
            />
            <button
              type="submit"
              disabled={!refinementInput.trim()}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-gradient-to-tr from-indigo-600 to-violet-600 text-white rounded-lg hover:shadow-lg disabled:opacity-50 disabled:shadow-none transition-all duration-200 hover:scale-105 active:scale-95"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sparkles, MessageSquareText, Eraser, Moon, Sun, ArrowRight, PenLine } from 'lucide-react';
import { ToneOption, OutputLanguage, MacroType, LengthOption, PerspectiveOption, ModelOption } from './types';
import { streamTransformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';
import { LanguageSelector } from './components/LanguageSelector';
import { MacroSelector } from './components/MacroSelector';
import { LengthSelector } from './components/LengthSelector';
import { PerspectiveSelector } from './components/PerspectiveSelector';
import { ModelSelector } from './components/ModelSelector';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');

  // Nuevo estado para la sugerencia de corrección (separado del texto final)
  const [correctionSuggestion, setCorrectionSuggestion] = useState<string | null>(null);

  // State initialization
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [selectedLanguage, setSelectedLanguage] = useState<OutputLanguage>(OutputLanguage.AUTO);
  const [selectedMacro, setSelectedMacro] = useState<MacroType>(MacroType.FULL);
  const [selectedLength, setSelectedLength] = useState<LengthOption>(LengthOption.ORIGINAL);
  const [selectedPerspective, setSelectedPerspective] = useState<PerspectiveOption>(PerspectiveOption.WE);
  const [selectedModel, setSelectedModel] = useState<ModelOption>(ModelOption.FLASH);
  const [issueTopic, setIssueTopic] = useState('');

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  // Función general para transformación
  const executeTransformation = async (refinement?: string) => {
    if (!inputText.trim() && !outputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setCorrectionSuggestion(null); // Limpiar sugerencias anteriores

    if (!refinement) {
        setOutputText(''); 
    } else {
        setOutputText(''); 
    }

    try {
      await streamTransformText({
        text: inputText,
        tones: selectedTones,
        targetLanguage: selectedLanguage,
        macroType: selectedMacro,
        lengthOption: selectedLength,
        perspective: selectedPerspective,
        model: selectedModel,
        issueTopic: issueTopic, 
        refinementInstruction: refinement,
        previousOutput: refinement ? outputText : undefined
      }, (chunk) => {
        setOutputText(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("Error de conexión con IA. Intenta de nuevo.");
    } finally {
      setIsLoading(false);
    }
  };

  // Función específica para revisar ortografía SIN reemplazar
  const handleCheckGrammar = async () => {
    if (!outputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setCorrectionSuggestion(''); // Iniciamos vacío

    try {
      // Usamos el servicio pero guardamos en 'correctionSuggestion'
      await streamTransformText({
        text: outputText, // El input es el texto que ya está en la salida
        tones: [], // Sin tonos
        targetLanguage: OutputLanguage.AUTO, // Mismo idioma
        macroType: MacroType.FULL, // Irrelevante, se sobreescribe con refinement
        lengthOption: LengthOption.ORIGINAL,
        perspective: selectedPerspective,
        model: ModelOption.FLASH, // Usamos flash para rapidez en corrección
        refinementInstruction: "Corrige estrictamente la ORTOGRAFÍA y GRAMÁTICA. No cambies el estilo, ni el tono, ni reescribas frases si son correctas. Solo devuelve el texto corregido exacto.",
        previousOutput: outputText
      }, (chunk) => {
        setCorrectionSuggestion(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("No se pudo revisar la ortografía.");
      setCorrectionSuggestion(null);
    } finally {
      setIsLoading(false);
    }
  };

  const handleApplyCorrection = () => {
    if (correctionSuggestion) {
      setOutputText(correctionSuggestion);
      setCorrectionSuggestion(null);
    }
  };

  const handleDiscardCorrection = () => {
    setCorrectionSuggestion(null);
  };

  const handleTransform = () => executeTransformation();

  const handleRefine = (instruction: string) => {
     executeTransformation(instruction);
  };

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setIssueTopic('');
    setCorrectionSuggestion(null);
    setError(null);
  };

  return (
    <div className="min-h-screen">

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl border-b border-gray-200/50 dark:border-slate-800 transition-colors duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative group">
               <div className="absolute inset-0 bg-indigo-500/30 blur-lg rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
               <div className="relative w-9 h-9 bg-gradient-to-br from-indigo-600 to-violet-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/20">
                 <Sparkles className="w-5 h-5" />
               </div>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-700 to-violet-600 dark:from-indigo-400 dark:to-violet-400 tracking-tight">
              EmpathIA
            </h1>
          </div>

          <div className="flex items-center gap-4">
            <button
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="p-2.5 rounded-full text-gray-500 dark:text-gray-400 hover:bg-gray-100/80 dark:hover:bg-slate-800/80 transition-all hover:scale-105 active:scale-95"
              title={isDarkMode ? "Modo Claro" : "Modo Oscuro"}
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-10">

        <div className="flex flex-col gap-6">

          {/* Controls Card */}
          <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-lg rounded-3xl p-6 shadow-xl shadow-indigo-900/5 border border-white/50 dark:border-slate-700/50 transition-colors duration-300">
            <div className="flex flex-col lg:flex-row gap-8 lg:items-start justify-between">

              <div className="flex flex-col gap-5 flex-1 w-full">
                {/* Structure & Length Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 w-full">
                  {/* Macro Selector */}
                  <div className="flex flex-col gap-2">
                    <span className="text-[11px] font-bold text-gray-400 dark:text-slate-500 uppercase tracking-widest ml-1">Estructura</span>
                    <MacroSelector 
                      selectedMacro={selectedMacro} 
                      onChange={setSelectedMacro} 
                      disabled={isLoading} 
                    />
                  </div>

                   {/* Length Selector */}
                   <div className="flex flex-col gap-2">
                    <span className="text-[11px] font-bold text-gray-400 dark:text-slate-500 uppercase tracking-widest ml-1">Longitud</span>
                    <LengthSelector
                      selectedLength={selectedLength}
                      onChange={setSelectedLength}
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {/* Optional Issue Input */}
                {selectedMacro === MacroType.FIRST && (
                  <div className="animate-slide-up bg-indigo-50/50 dark:bg-indigo-900/10 p-4 rounded-2xl border border-indigo-100/50 dark:border-indigo-800/30 flex flex-col sm:flex-row sm:items-center gap-4">
                    <label className="text-xs font-bold text-indigo-400 dark:text-indigo-300 uppercase tracking-wider flex items-center gap-2 whitespace-nowrap">
                      <PenLine className="w-4 h-4" />
                      Tema del Problema
                    </label>
                    <input
                      type="text"
                      value={issueTopic}
                      onChange={(e) => setIssueTopic(e.target.value)}
                      placeholder="Ej: suscripción, pago rechazado..."
                      className="flex-1 px-4 py-2 rounded-xl border border-indigo-200 dark:border-indigo-800/50 bg-white dark:bg-slate-900 text-sm focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all placeholder:text-gray-400 dark:placeholder:text-slate-600"
                    />
                  </div>
                )}
              </div>

              {/* AI & Language Selectors */}
               <div className="flex flex-col gap-2 w-full lg:w-auto">
                  <span className="text-[11px] font-bold text-gray-400 dark:text-slate-500 uppercase tracking-widest ml-1 lg:text-right">Configuración IA</span>
                  <div className="flex flex-col sm:flex-row gap-3 lg:ml-auto">
                    <ModelSelector 
                        selectedModel={selectedModel}
                        onChange={setSelectedModel}
                        disabled={isLoading}
                    />
                    <LanguageSelector 
                        selectedLanguage={selectedLanguage}
                        onChange={setSelectedLanguage}
                        disabled={isLoading}
                    />
                  </div>
               </div>
            </div>

            <div className="h-px w-full bg-gradient-to-r from-transparent via-gray-200 dark:via-slate-700 to-transparent my-6"></div>

            {/* Tones & Action Row */}
            <div className="flex flex-col xl:flex-row items-end justify-between gap-6">
              <div className="flex flex-col gap-2 w-full xl:w-auto">
                <span className="text-[11px] font-bold text-gray-400 dark:text-slate-500 uppercase tracking-widest ml-1 text-center xl:text-left">Tonos Emocionales</span>
                <div className="flex flex-wrap justify-center xl:justify-start gap-2">
                  {Object.values(ToneOption).map((tone) => (
                    <OptionButton
                      key={tone}
                      option={tone}
                      isSelected={selectedTones.includes(tone)}
                      onClick={() => toggleTone(tone)}
                      disabled={isLoading}
                    />
                  ))}
                </div>
              </div>

              {/* Actions Right Side */}
              <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto justify-end mt-4 xl:mt-0">
                <PerspectiveSelector
                  selectedPerspective={selectedPerspective}
                  onChange={setSelectedPerspective}
                  disabled={isLoading}
                />

                <button
                  onClick={handleTransform}
                  disabled={isLoading || !inputText.trim()}
                  className={`
                    group relative w-full sm:w-auto px-8 py-3 rounded-xl flex items-center justify-center gap-2.5
                    font-bold text-white transition-all duration-300 shadow-xl shadow-indigo-500/20
                    overflow-hidden
                    ${isLoading || !inputText.trim() 
                      ? 'bg-slate-400 dark:bg-slate-600 cursor-not-allowed opacity-70 shadow-none' 
                      : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:scale-[1.02] active:scale-[0.98] hover:shadow-indigo-500/40'}
                  `}
                >
                  {/* Sheen effect */}
                  {!isLoading && inputText.trim() && (
                    <div className="absolute inset-0 -translate-x-full group-hover:translate-x-full transition-transform duration-700 bg-gradient-to-r from-transparent via-white/20 to-transparent skew-x-12"></div>
                  )}

                  {isLoading ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  ) : (
                    <Sparkles className="w-5 h-5" />
                  )}
                  <span className="relative">{isLoading ? 'Procesando...' : 'Transformar'}</span>
                  {!isLoading && <ArrowRight className="w-4 h-4 opacity-80 relative group-hover:translate-x-1 transition-transform" />}
                </button>
              </div>
            </div>
          </div>

          {/* Main Interface Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-[550px] lg:h-[650px]">

            {/* Input Section */}
            <div className="flex flex-col h-full bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm rounded-2xl shadow-sm border border-white/20 dark:border-slate-700 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-500/40 transition-all duration-300 hover:bg-white/70 dark:hover:bg-slate-800/70">
              <div className="flex items-center justify-between px-5 py-3 border-b border-gray-100/50 dark:border-slate-700/50">
                <label htmlFor="input-text" className="text-xs font-bold text-gray-500 dark:text-slate-400 uppercase tracking-wider flex items-center gap-2">
                  <MessageSquareText className="w-4 h-4" />
                  Entrada
                </label>
                <button 
                  onClick={handleClear}
                  className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors px-2 py-1 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
                  disabled={!inputText}
                >
                  <Eraser className="w-3.5 h-3.5" />
                  Borrar
                </button>
              </div>
              <textarea
                id="input-text"
                className="flex-1 w-full p-6 resize-none focus:outline-none text-[15px] sm:text-base text-slate-700 dark:text-slate-200 placeholder:text-slate-400/70 dark:placeholder:text-slate-600 bg-transparent leading-relaxed"
                placeholder="Escribe o pega el cuerpo de tu respuesta aquí..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                disabled={isLoading}
              />
               <div className="px-4 py-2 border-t border-gray-100/50 dark:border-slate-700/50 flex justify-end">
                  <span className="text-[10px] font-medium text-gray-400 dark:text-slate-600 bg-gray-100 dark:bg-slate-800 px-2 py-0.5 rounded-md">
                    {inputText.length} chars
                  </span>
               </div>
            </div>

            {/* Output Section */}
            <div className="h-full">
              <OutputSection 
                originalText={inputText}
                transformedText={outputText}
                correctionSuggestion={correctionSuggestion}
                isLoading={isLoading}
                onRetry={handleTransform}
                onRefine={handleRefine}
                onUpdateText={setOutputText}
                onCheckGrammar={handleCheckGrammar}
                onApplyCorrection={handleApplyCorrection}
                onDiscardCorrection={handleDiscardCorrection}
              />
            </div>
          </div>

          {error && (
            <div className="bg-red-50/90 dark:bg-red-900/20 backdrop-blur text-red-600 dark:text-red-300 px-4 py-3 rounded-xl text-center border border-red-100 dark:border-red-900/30 text-sm animate-fade-in shadow-lg shadow-red-500/5">
              {error}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Copy, Check, GitCompare, Eye, Send, Sparkles, Languages, ArrowDownNarrowWide, Briefcase, Wand2, SpellCheck2, X } from 'lucide-react';
import { DiffView } from './DiffView';
import { VariableManager } from './VariableManager';

interface OutputSectionProps {
  originalText: string;
  transformedText: string;
  correctionSuggestion: string | null;
  isLoading: boolean;
  onRetry: () => void;
  onRefine: (instruction: string) => void;
  onUpdateText: (text: string) => void;
  onCheckGrammar: () => void;
  onApplyCorrection: () => void;
  onDiscardCorrection: () => void;
}

type ViewMode = 'final' | 'diff';

export const OutputSection: React.FC<OutputSectionProps> = ({ 
  originalText, 
  transformedText, 
  correctionSuggestion,
  isLoading, 
  onRetry,
  onRefine,
  onUpdateText,
  onCheckGrammar,
  onApplyCorrection,
  onDiscardCorrection
}) => {
  const [copied, setCopied] = useState(false);
  const [viewMode, setViewMode] = useState<ViewMode>('final');
  const [refinementInput, setRefinementInput] = useState('');

  const isCorrecting = correctionSuggestion !== null;

  const handleCopy = async () => {
    if (!transformedText) return;
    try {
      await navigator.clipboard.writeText(transformedText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const handleRefineSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!refinementInput.trim() || isLoading) return;
    onRefine(refinementInput);
    setRefinementInput('');
  };

  const handleQuickAction = (action: string) => {
    onRefine(action);
  };

  if (!transformedText && !isLoading) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-gray-400 dark:text-slate-500 p-8">
        <div className="w-20 h-20 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mb-6 animate-pulse">
            <Wand2 className="w-8 h-8 text-indigo-200 dark:text-slate-600" />
        </div>
        <h3 className="text-lg font-semibold text-gray-700 dark:text-slate-300 mb-2">Listo para Transformar</h3>
        <p className="text-sm text-center max-w-xs opacity-70 leading-relaxed">
          Configura tus preferencias arriba y presiona el botón para ver la magia ocurrir.
        </p>
      </div>
    );
  }

  // Si estamos corrigiendo, mostramos la vista Diff entre lo actual y la corrección
  // Si no, mostramos lo normal (viewMode decide si es final o diff con original)
  const currentViewMode = isCorrecting ? 'diff' : viewMode;
  const textToCompareOriginal = isCorrecting ? transformedText : originalText;
  const textToCompareModified = isCorrecting ? (correctionSuggestion || '') : transformedText;

  return (
    <div className={`relative flex flex-col h-full bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm rounded-2xl shadow-sm border ${isCorrecting ? 'border-amber-400 dark:border-amber-600 ring-2 ring-amber-500/10' : 'border-white/20 dark:border-slate-700'} overflow-hidden transition-all duration-300 group`}>

      {/* Header with Tabs */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100/50 dark:border-slate-700/50">

        {isCorrecting ? (
           <div className="flex items-center gap-2 text-amber-600 dark:text-amber-400 font-semibold text-sm animate-pulse">
              <SpellCheck2 className="w-4 h-4" />
              <span>Revisando Ortografía...</span>
           </div>
        ) : (
          <div className="flex bg-gray-100/80 dark:bg-slate-900/50 p-1 rounded-lg">
            <button
              onClick={() => setViewMode('final')}
              className={`flex items-center gap-1.5 px-3 py-1 text-xs font-semibold rounded-md transition-all ${viewMode === 'final' ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'}`}
            >
              <Eye className="w-3.5 h-3.5" />
              Vista Final
            </button>
            <button
              onClick={() => setViewMode('diff')}
              className={`flex items-center gap-1.5 px-3 py-1 text-xs font-semibold rounded-md transition-all ${viewMode === 'diff' ? 'bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-400 shadow-sm' : 'text-gray-500 dark:text-slate-400 hover:text-gray-700 dark:hover:text-slate-200'}`}
            >
              <GitCompare className="w-3.5 h-3.5" />
              Cambios
            </button>
          </div>
        )}

        {!isLoading && transformedText && !isCorrecting && (
          <div className="flex gap-2">
            <button
              onClick={onCheckGrammar}
              title="Revisar ortografía y ver errores"
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border bg-white dark:bg-slate-800 text-amber-600 dark:text-amber-400 border-gray-200 dark:border-slate-600 hover:border-amber-300 dark:hover:border-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20 transition-all duration-200"
            >
               <SpellCheck2 className="w-3.5 h-3.5" />
               <span className="hidden sm:inline">Revisar</span>
            </button>

            <button
              onClick={handleCopy}
              className={`
                flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-lg border transition-all duration-200
                ${copied 
                    ? 'bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-400 border-green-200 dark:border-green-800' 
                    : 'bg-white dark:bg-slate-800 text-gray-600 dark:text-slate-300 border-gray-200 dark:border-slate-600 hover:border-indigo-300 dark:hover:border-indigo-500 hover:text-indigo-600'
                }
              `}
            >
              {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
              {copied ? 'Copiado' : 'Copiar'}
            </button>
          </div>
        )}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 p-6 overflow-y-auto relative bg-white/40 dark:bg-transparent">

        {!isCorrecting && <VariableManager text={transformedText} onUpdateText={onUpdateText} />}

        {isLoading && !transformedText ? (
          <div className="space-y-4 animate-pulse mt-4">
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-3/4"></div>
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-full"></div>
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-5/6"></div>
            <div className="h-4 bg-gray-200/60 dark:bg-slate-700/60 rounded w-2/3"></div>
          </div>
        ) : (
          currentViewMode === 'final' ? (
            <div className="h-full flex flex-col animate-fade-in">
                {isLoading && <div className="text-xs text-indigo-500 mb-2 animate-pulse font-medium">✨ Generando...</div>}
                <textarea
                    className="flex-1 w-full bg-transparent border-none outline-none resize-none text-gray-700 dark:text-slate-200 leading-relaxed font-normal text-[15px] sm:text-base selection:bg-indigo-100 selection:text-indigo-900 placeholder:text-gray-400 p-0"
                    value={transformedText}
                    onChange={(e) => onUpdateText(e.target.value)}
                    spellCheck={true}
                    lang="es" 
                    placeholder="El resultado aparecerá aquí..."
                />
            </div>
          ) : (
            <div className="flex flex-col gap-2">
                {isCorrecting && (
                  <div className="text-xs text-gray-500 mb-2 flex items-center justify-between">
                     <span>Comparando: <strong className="text-red-500">Tu texto</strong> vs <strong className="text-green-600">Corrección</strong></span>
                  </div>
                )}
                <DiffView original={textToCompareOriginal} modified={textToCompareModified} />
                {isCorrecting && isLoading && <div className="mt-4 text-xs text-amber-500 animate-pulse">Analizando ortografía...</div>}
            </div>
          )
        )}
      </div>

      {/* Overlay Actions for Correction */}
      {isCorrecting && !isLoading && (
        <div className="absolute bottom-0 left-0 right-0 p-4 bg-white/95 dark:bg-slate-900/95 backdrop-blur border-t border-amber-200 dark:border-amber-900/50 flex flex-col sm:flex-row items-center justify-between gap-3 animate-slide-up z-20 shadow-lg">
            <div className="text-sm text-gray-600 dark:text-slate-300">
                ¿Deseas aplicar estas correcciones?
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
                <button 
                  onClick={onDiscardCorrection}
                  className="flex-1 sm:flex-none px-4 py-2 text-xs font-bold text-gray-600 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-slate-800 rounded-lg transition-colors border border-transparent hover:border-gray-200 dark:hover:border-slate-700"
                >
                    Descartar
                </button>
                <button 
                   onClick={onApplyCorrection}
                   className="flex-1 sm:flex-none px-6 py-2 text-xs font-bold text-white bg-green-600 hover:bg-green-700 rounded-lg shadow-lg shadow-green-600/20 transition-all flex items-center justify-center gap-2"
                >
                    <Check className="w-3.5 h-3.5" />
                    Aplicar Cambios
                </button>
            </div>
        </div>
      )}

      {/* Footer: Quick Actions & Refinement (Only show if NOT correcting) */}
      {!isLoading && transformedText && !isCorrecting && (
        <div className="border-t border-gray-100 dark:border-slate-700 bg-gray-50/80 dark:bg-slate-900/40 p-3 space-y-3 backdrop-blur-md">

          {/* Quick Actions Chips */}
          <div className="flex flex-wrap gap-2 justify-center sm:justify-start">
             <button onClick={() => handleQuickAction("Hazlo más corto")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <ArrowDownNarrowWide className="w-3 h-3" /> Más Corto
             </button>
             <button onClick={() => handleQuickAction("Hazlo más formal y profesional")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <Briefcase className="w-3 h-3" /> Más Formal
             </button>
             <button onClick={() => handleQuickAction("Traducir a Inglés")} className="flex items-center gap-1.5 px-3 py-1 text-[11px] font-medium bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded-full hover:border-indigo-300 dark:hover:border-indigo-500 transition-colors text-gray-600 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-300 shadow-sm">
                <Languages className="w-3 h-3" /> Inglés
             </button>
          </div>

          {/* Chat Input */}
          <form onSubmit={handleRefineSubmit} className="relative group">
            <div className="absolute inset-0 bg-gradient-to-r from-indigo-500/20 to-violet-500/20 rounded-xl blur opacity-0 group-focus-within:opacity-100 transition-opacity duration-500"></div>
            <input
              type="text"
              value={refinementInput}
              onChange={(e) => setRefinementInput(e.target.value)}
              placeholder="✨ ¿Quieres ajustar algo? (Ej: 'Quita la disculpa', 'Hazlo más amable')"
              className="relative w-full pl-4 pr-10 py-3 text-sm rounded-xl border border-gray-200 dark:border-slate-600 bg-white dark:bg-slate-800 focus:border-indigo-400 dark:focus:border-indigo-500 outline-none transition-all shadow-sm focus:shadow-md dark:text-slate-200 placeholder:text-gray-400"
            />
            <button
              type="submit"
              disabled={!refinementInput.trim()}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 bg-gradient-to-tr from-indigo-600 to-violet-600 text-white rounded-lg hover:shadow-lg disabled:opacity-50 disabled:shadow-none transition-all duration-200 hover:scale-105 active:scale-95"
            >
              <Send className="w-3.5 h-3.5" />
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Sparkles, MessageSquareText, Eraser, Moon, Sun, ArrowRight, PenLine } from 'lucide-react';
import { ToneOption, OutputLanguage, MacroType, LengthOption, PerspectiveOption, ModelOption } from './types';
import { streamTransformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';
import { LanguageSelector } from './components/LanguageSelector';
import { MacroSelector } from './components/MacroSelector';
import { LengthSelector } from './components/LengthSelector';
import { PerspectiveSelector } from './components/PerspectiveSelector';
import { ModelSelector } from './components/ModelSelector';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');

  // Nuevo estado para la sugerencia de corrección (separado del texto final)
  const [correctionSuggestion, setCorrectionSuggestion] = useState<string | null>(null);

  // State initialization
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [selectedLanguage, setSelectedLanguage] = useState<OutputLanguage>(OutputLanguage.AUTO);
  const [selectedMacro, setSelectedMacro] = useState<MacroType>(MacroType.FULL);
  const [selectedLength, setSelectedLength] = useState<LengthOption>(LengthOption.ORIGINAL);
  const [selectedPerspective, setSelectedPerspective] = useState<PerspectiveOption>(PerspectiveOption.WE);
  const [selectedModel, setSelectedModel] = useState<ModelOption>(ModelOption.FLASH);
  const [issueTopic, setIssueTopic] = useState('');

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // DARK MODE BY DEFAULT
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  // Función general para transformación
  const executeTransformation = async (refinement?: string) => {
    if (!inputText.trim() && !outputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setCorrectionSuggestion(null); // Limpiar sugerencias anteriores

    if (!refinement) {
        setOutputText(''); 
    } else {
        setOutputText(''); 
    }

    try {
      await streamTransformText({
        text: inputText,
        tones: selectedTones,
        targetLanguage: selectedLanguage,
        macroType: selectedMacro,
        lengthOption: selectedLength,
        perspective: selectedPerspective,
        model: selectedModel,
        issueTopic: issueTopic, 
        refinementInstruction: refinement,
        previousOutput: refinement ? outputText : undefined
      }, (chunk) => {
        setOutputText(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("Error de conexión con IA. Intenta de nuevo.");
    } finally {
      setIsLoading(false);
    }
  };

  // Función específica para revisar ortografía SIN reemplazar
  const handleCheckGrammar = async () => {
    if (!outputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setCorrectionSuggestion(''); // Iniciamos vacío

    try {
      // Usamos el servicio pero guardamos en 'correctionSuggestion'
      await streamTransformText({
        text: outputText, // El input es el texto que ya está en la salida
        tones: [], // Sin tonos
        targetLanguage: OutputLanguage.AUTO, // Mismo idioma
        macroType: MacroType.FULL, // Irrelevante, se sobreescribe con refinement
        lengthOption: LengthOption.ORIGINAL,
        perspective: selectedPerspective,
        model: ModelOption.FLASH, // Usamos flash para rapidez en corrección
        refinementInstruction: "Corrige estrictamente la ORTOGRAFÍA y GRAMÁTICA. No cambies el estilo, ni el tono, ni reescribas frases si son correctas. Solo devuelve el texto corregido exacto.",
        previousOutput: outputText
      }, (chunk) => {
        setCorrectionSuggestion(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("No se pudo revisar la ortografía.");
      setCorrectionSuggestion(null);
    } finally {
      setIsLoading(false);
    }
  };

  const handleApplyCorrection = () => {
    if (correctionSuggestion) {
      setOutputText(correctionSuggestion);
      setCorrectionSuggestion(null);
    }
  };

  const handleDiscardCorrection = () => {
    setCorrectionSuggestion(null);
  };

  const handleTransform = () => executeTransformation();

  const handleRefine = (instruction: string) => {
     executeTransformation(instruction);
  };

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setIssueTopic('');
    setCorrectionSuggestion(null);
    setError(null);
  };

  return (
    <div className="min-h-screen">

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl border-b border-gray-200/50 dark:border-slate-800 transition-colors duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative group cursor-pointer">
               <div className="absolute inset-0 bg-indigo-500/30 blur-lg rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
               {/* Custom EmpathIA Logo */}
               <div className="relative w-10 h-10 bg-gradient-to-br from-indigo-600 to-violet-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/20 group-hover:scale-105 transition-transform duration-300">
                 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-6 h-6">
                    <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z" className="text-indigo-200" fill="currentColor" fillOpacity="0.2"/>
                    <path d="M12 7.5c-3.5 0-4.5 3-4.5 3s-1.5-1.5-3.5-1.5-3.5 2-3.5 4.5c0 3.5 4.5 6.5 7.5 8 3-1.5 7.5-4.5 7.5-8 0-2.5-1.5-4.5-3.5-4.5s-3.5 1.5-3.5 1.5-1-3-4.5-3z" fill="white" stroke="none" transform="scale(0.6) translate(8, 8)"/>
                 </svg>
               </div>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-700 to-violet-600 dark:from-indigo-400 dark:to-violet-400 tracking-tight">
              EmpathIA
            </h1>
          </div>

          <div className="flex items-center gap-4">
            <button
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="p-2.5 rounded-full text-gray-500 dark:text-slate-300 hover:bg-gray-100/80 dark:hover:bg-slate-800/80 transition-all hover:scale-105 active:scale-95 bg-transparent dark:bg-slate-800/50"
              title={isDarkMode ? "Modo Claro" : "Modo Oscuro"}
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-10">

        <div className="flex flex-col gap-6">

          {/* Controls Card */}
          <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-lg rounded-3xl p-6 shadow-xl shadow-indigo-900/5 border border-white/50 dark:border-slate-700/50 transition-colors duration-300">
            <div className="flex flex-col lg:flex-row gap-8 lg:items-start justify-between">

              <div className="flex flex-col gap-5 flex-1 w-full">
                {/* Structure & Length Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 w-full">
                  {/* Macro Selector */}
                  <div className="flex flex-col gap-2">
                    <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1">Estructura</span>
                    <MacroSelector 
                      selectedMacro={selectedMacro} 
                      onChange={setSelectedMacro} 
                      disabled={isLoading} 
                    />
                  </div>

                   {/* Length Selector */}
                   <div className="flex flex-col gap-2">
                    <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1">Longitud</span>
                    <LengthSelector
                      selectedLength={selectedLength}
                      onChange={setSelectedLength}
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {/* Optional Issue Input */}
                {selectedMacro === MacroType.FIRST && (
                  <div className="animate-slide-up bg-indigo-50/50 dark:bg-indigo-900/20 p-4 rounded-2xl border border-indigo-100/50 dark:border-indigo-800/30 flex flex-col sm:flex-row sm:items-center gap-4">
                    <label className="text-xs font-bold text-indigo-400 dark:text-indigo-300 uppercase tracking-wider flex items-center gap-2 whitespace-nowrap">
                      <PenLine className="w-4 h-4" />
                      Tema del Problema
                    </label>
                    <input
                      type="text"
                      value={issueTopic}
                      onChange={(e) => setIssueTopic(e.target.value)}
                      placeholder="Ej: suscripción, pago rechazado..."
                      className="flex-1 px-4 py-2 rounded-xl border border-indigo-200 dark:border-indigo-800/50 bg-white dark:bg-slate-900 dark:text-slate-200 text-sm focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all placeholder:text-gray-400 dark:placeholder:text-slate-500"
                    />
                  </div>
                )}
              </div>

              {/* AI & Language Selectors */}
               <div className="flex flex-col gap-2 w-full lg:w-auto">
                  <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1 lg:text-right">Configuración IA</span>
                  <div className="flex flex-col sm:flex-row gap-3 lg:ml-auto">
                    <ModelSelector 
                        selectedModel={selectedModel}
                        onChange={setSelectedModel}
                        disabled={isLoading}
                    />
                    <LanguageSelector 
                        selectedLanguage={selectedLanguage}
                        onChange={setSelectedLanguage}
                        disabled={isLoading}
                    />
                  </div>
               </div>
            </div>

            <div className="h-px w-full bg-gradient-to-r from-transparent via-gray-200 dark:via-slate-700 to-transparent my-6"></div>

            {/* Tones & Action Row */}
            <div className="flex flex-col xl:flex-row items-end justify-between gap-6">
              <div className="flex flex-col gap-2 w-full xl:w-auto">
                <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1 text-center xl:text-left">Tonos Emocionales</span>
                <div className="flex flex-wrap justify-center xl:justify-start gap-2">
                  {Object.values(ToneOption).map((tone) => (
                    <OptionButton
                      key={tone}
                      option={tone}
                      isSelected={selectedTones.includes(tone)}
                      onClick={() => toggleTone(tone)}
                      disabled={isLoading}
                    />
                  ))}
                </div>
              </div>

              {/* Actions Right Side */}
              <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto justify-end mt-4 xl:mt-0">
                <PerspectiveSelector
                  selectedPerspective={selectedPerspective}
                  onChange={setSelectedPerspective}
                  disabled={isLoading}
                />

                <button
                  onClick={handleTransform}
                  disabled={isLoading || !inputText.trim()}
                  className={`
                    group relative w-full sm:w-auto px-8 py-3 rounded-xl flex items-center justify-center gap-2.5
                    font-bold text-white transition-all duration-300 shadow-xl shadow-indigo-500/20
                    overflow-hidden
                    ${isLoading || !inputText.trim() 
                      ? 'bg-slate-400 dark:bg-slate-600 cursor-not-allowed opacity-70 shadow-none' 
                      : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:scale-[1.02] active:scale-[0.98] hover:shadow-indigo-500/40'}
                  `}
                >
                  {/* Sheen effect */}
                  {!isLoading && inputText.trim() && (
                    <div className="absolute inset-0 -translate-x-full group-hover:translate-x-full transition-transform duration-700 bg-gradient-to-r from-transparent via-white/20 to-transparent skew-x-12"></div>
                  )}

                  {isLoading ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  ) : (
                    <Sparkles className="w-5 h-5" />
                  )}
                  <span className="relative">{isLoading ? 'Procesando...' : 'Transformar'}</span>
                  {!isLoading && <ArrowRight className="w-4 h-4 opacity-80 relative group-hover:translate-x-1 transition-transform" />}
                </button>
              </div>
            </div>
          </div>

          {/* Main Interface Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-[550px] lg:h-[650px]">

            {/* Input Section */}
            <div className="flex flex-col h-full bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm rounded-2xl shadow-sm border border-white/20 dark:border-slate-700 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-500/40 transition-all duration-300 hover:bg-white/70 dark:hover:bg-slate-800/70">
              <div className="flex items-center justify-between px-5 py-3 border-b border-gray-100/50 dark:border-slate-700/50">
                <label htmlFor="input-text" className="text-xs font-bold text-gray-500 dark:text-slate-300 uppercase tracking-wider flex items-center gap-2">
                  <MessageSquareText className="w-4 h-4" />
                  Entrada
                </label>
                <button 
                  onClick={handleClear}
                  className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors px-2 py-1 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
                  disabled={!inputText}
                >
                  <Eraser className="w-3.5 h-3.5" />
                  Borrar
                </button>
              </div>
              <textarea
                id="input-text"
                className="flex-1 w-full p-6 resize-none focus:outline-none text-[15px] sm:text-base text-slate-700 dark:text-slate-100 placeholder:text-slate-400/70 dark:placeholder:text-slate-500 bg-transparent leading-relaxed"
                placeholder="Escribe o pega el cuerpo de tu respuesta aquí..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                disabled={isLoading}
              />
               <div className="px-4 py-2 border-t border-gray-100/50 dark:border-slate-700/50 flex justify-end">
                  <span className="text-[10px] font-medium text-gray-400 dark:text-slate-500 bg-gray-100 dark:bg-slate-800 px-2 py-0.5 rounded-md">
                    {inputText.length} chars
                  </span>
               </div>
            </div>

            {/* Output Section */}
            <div className="h-full">
              <OutputSection 
                originalText={inputText}
                transformedText={outputText}
                correctionSuggestion={correctionSuggestion}
                isLoading={isLoading}
                onRetry={handleTransform}
                onRefine={handleRefine}
                onUpdateText={setOutputText}
                onCheckGrammar={handleCheckGrammar}
                onApplyCorrection={handleApplyCorrection}
                onDiscardCorrection={handleDiscardCorrection}
              />
            </div>
          </div>

          {error && (
            <div className="bg-red-50/90 dark:bg-red-900/20 backdrop-blur text-red-600 dark:text-red-300 px-4 py-3 rounded-xl text-center border border-red-100 dark:border-red-900/30 text-sm animate-fade-in shadow-lg shadow-red-500/5">
              {error}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

