                                ? 'bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-300 border-red-200 dark:border-red-700 shadow-sm' 
                                : 'bg-gray-100/80 dark:bg-slate-900/80 text-gray-500 dark:text-slate-400 border-gray-200/50 dark:border-slate-800 hover:text-gray-700 dark:hover:text-slate-200'
