  );
};

import React, { useState, useEffect } from 'react';
import { Sparkles, MessageSquareText, Eraser, Moon, Sun, ArrowRight, PenLine, Flag, BookOpen, ShieldAlert } from 'lucide-react';
import { ToneOption, OutputLanguage, MacroType, LengthOption, PerspectiveOption, ModelOption } from './types';
import { streamTransformText } from './services/geminiService';
import { OptionButton } from './components/OptionButton';
import { OutputSection } from './components/OutputSection';
import { LanguageSelector } from './components/LanguageSelector';
import { MacroSelector } from './components/MacroSelector';
import { LengthSelector } from './components/LengthSelector';
import { PerspectiveSelector } from './components/PerspectiveSelector';
import { ModelSelector } from './components/ModelSelector';
import { Logo } from './components/Logo';
import { InfoModal } from './components/InfoModal';

const App: React.FC = () => {
  const [inputText, setInputText] = useState('');
  const [outputText, setOutputText] = useState('');

  // Nuevo estado para la sugerencia de corrección (separado del texto final)
  const [correctionSuggestion, setCorrectionSuggestion] = useState<string | null>(null);

  // State initialization
  const [selectedTones, setSelectedTones] = useState<ToneOption[]>([ToneOption.EMPATHY]);
  const [selectedLanguage, setSelectedLanguage] = useState<OutputLanguage>(OutputLanguage.AUTO);
  const [selectedMacro, setSelectedMacro] = useState<MacroType>(MacroType.FULL);
  const [selectedLength, setSelectedLength] = useState<LengthOption>(LengthOption.ORIGINAL);
  const [selectedPerspective, setSelectedPerspective] = useState<PerspectiveOption>(PerspectiveOption.WE);
  const [selectedModel, setSelectedModel] = useState<ModelOption>(ModelOption.FLASH);
  const [issueTopic, setIssueTopic] = useState('');
  const [isClosingFinal, setIsClosingFinal] = useState(false);

  // Modal States
  const [isGuideOpen, setIsGuideOpen] = useState(false);
  const [isDisclaimerOpen, setIsDisclaimerOpen] = useState(false);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // DARK MODE BY DEFAULT
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTone = (tone: ToneOption) => {
    setSelectedTones(prev => {
      if (prev.includes(tone)) {
        return prev.filter(t => t !== tone);
      }
      return [...prev, tone];
    });
  };

  // Función general para transformación
  const executeTransformation = async (refinement?: string) => {
    if (!inputText.trim() && !outputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setCorrectionSuggestion(null); // Limpiar sugerencias anteriores

    if (!refinement) {
        setOutputText(''); 
    } else {
        setOutputText(''); 
    }

    try {
      await streamTransformText({
        text: inputText,
        tones: selectedTones,
        targetLanguage: selectedLanguage,
        macroType: selectedMacro,
        lengthOption: selectedLength,
        perspective: selectedPerspective,
        model: selectedModel,
        issueTopic: issueTopic, 
        refinementInstruction: refinement,
        previousOutput: refinement ? outputText : undefined,
        isClosingFinal: isClosingFinal
      }, (chunk) => {
        setOutputText(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("Error de conexión con IA. Intenta de nuevo.");
    } finally {
      setIsLoading(false);
    }
  };

  // Función específica para revisar ortografía SIN reemplazar
  const handleCheckGrammar = async () => {
    if (!outputText.trim()) return;

    setIsLoading(true);
    setError(null);
    setCorrectionSuggestion(''); // Iniciamos vacío

    try {
      // Usamos el servicio pero guardamos en 'correctionSuggestion'
      await streamTransformText({
        text: outputText, // El input es el texto que ya está en la salida
        tones: [], // Sin tonos
        targetLanguage: OutputLanguage.AUTO, // Mismo idioma
        macroType: MacroType.FULL, // Irrelevante, se sobreescribe con refinement
        lengthOption: LengthOption.ORIGINAL,
        perspective: selectedPerspective,
        model: ModelOption.FLASH, // Usamos flash para rapidez en corrección
        refinementInstruction: "Corrige estrictamente la ORTOGRAFÍA y GRAMÁTICA. No cambies el estilo, ni el tono, ni reescribas frases si son correctas. Solo devuelve el texto corregido exacto.",
        previousOutput: outputText
      }, (chunk) => {
        setCorrectionSuggestion(chunk);
      });

    } catch (err: any) {
      console.error(err);
      setError("No se pudo revisar la ortografía.");
      setCorrectionSuggestion(null);
    } finally {
      setIsLoading(false);
    }
  };

  const handleApplyCorrection = () => {
    if (correctionSuggestion) {
      setOutputText(correctionSuggestion);
      setCorrectionSuggestion(null);
    }
  };

  const handleDiscardCorrection = () => {
    setCorrectionSuggestion(null);
  };

  const handleTransform = () => executeTransformation();

  const handleRefine = (instruction: string) => {
     executeTransformation(instruction);
  };

  const handleClear = () => {
    setInputText('');
    setOutputText('');
    setIssueTopic('');
    setCorrectionSuggestion(null);
    setError(null);
  };

  return (
    <div className="min-h-screen">

      {/* Modals */}
      <InfoModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} type="GUIDE" />
      <InfoModal isOpen={isDisclaimerOpen} onClose={() => setIsDisclaimerOpen(false)} type="DISCLAIMER" />

      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl border-b border-gray-200/50 dark:border-slate-800 transition-colors duration-300">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="relative group cursor-pointer">
               <div className="absolute inset-0 bg-indigo-500/30 blur-lg rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
               {/* Custom EmpathIA Logo */}
               <div className="relative w-10 h-10 group-hover:scale-105 transition-transform duration-300 rounded-xl overflow-hidden shadow-lg shadow-indigo-500/20 bg-white dark:bg-slate-900 flex items-center justify-center p-1.5 border border-indigo-50 dark:border-indigo-900/50">
                  <Logo className="w-full h-full text-indigo-600 dark:text-indigo-400" />
               </div>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-700 to-violet-600 dark:from-indigo-400 dark:to-violet-400 tracking-tight">
              EmpathIA
            </h1>
          </div>

          <div className="flex items-center gap-3">
            {/* Guide Button */}
            <button
              onClick={() => setIsGuideOpen(true)}
              className="p-2 rounded-full text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all cursor-pointer"
              title="Guía de Uso"
            >
              <BookOpen className="w-5 h-5" />
            </button>

            {/* Disclaimer Button */}
             <button
              onClick={() => setIsDisclaimerOpen(true)}
              className="p-2 rounded-full text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-all cursor-pointer"
              title="Disclaimer / Aviso Legal"
            >
              <ShieldAlert className="w-5 h-5" />
            </button>

            {/* Theme Toggle */}
            <button
              onClick={() => setIsDarkMode(!isDarkMode)}
              className="p-2.5 rounded-full text-gray-500 dark:text-slate-300 hover:bg-gray-100/80 dark:hover:bg-slate-800/80 transition-all hover:scale-105 active:scale-95 bg-transparent dark:bg-slate-800/50"
              title={isDarkMode ? "Modo Claro" : "Modo Oscuro"}
            >
              {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 lg:py-10">

        <div className="flex flex-col gap-6">

          {/* Controls Card */}
          <div className="bg-white/80 dark:bg-slate-900/60 backdrop-blur-lg rounded-3xl p-6 shadow-xl shadow-indigo-900/5 border border-white/50 dark:border-slate-700/50 transition-colors duration-300">
            <div className="flex flex-col lg:flex-row gap-8 lg:items-start justify-between">

              <div className="flex flex-col gap-5 flex-1 w-full">
                {/* Structure & Length Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5 w-full">
                  {/* Macro Selector */}
                  <div className="flex flex-col gap-2">
                    <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1">Estructura</span>
                    <MacroSelector 
                      selectedMacro={selectedMacro} 
                      onChange={setSelectedMacro} 
                      disabled={isLoading} 
                    />
                  </div>

                   {/* Length Selector */}
                   <div className="flex flex-col gap-2">
                    <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1">Longitud</span>
                    <LengthSelector
                      selectedLength={selectedLength}
                      onChange={setSelectedLength}
                      disabled={isLoading}
                    />
                  </div>
                </div>

                {/* Optional Issue Input */}
                {selectedMacro === MacroType.FIRST && (
                  <div className="animate-slide-up bg-indigo-50/50 dark:bg-indigo-900/20 p-4 rounded-2xl border border-indigo-100/50 dark:border-indigo-800/30 flex flex-col sm:flex-row sm:items-center gap-4">
                    <label className="text-xs font-bold text-indigo-400 dark:text-indigo-300 uppercase tracking-wider flex items-center gap-2 whitespace-nowrap">
                      <PenLine className="w-4 h-4" />
                      Tema del Problema
                    </label>
                    <input
                      type="text"
                      value={issueTopic}
                      onChange={(e) => setIssueTopic(e.target.value)}
                      placeholder="Ej: suscripción, pago rechazado..."
                      className="flex-1 px-4 py-2 rounded-xl border border-indigo-200 dark:border-indigo-800/50 bg-white dark:bg-slate-900 dark:text-slate-200 text-sm focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all placeholder:text-gray-400 dark:placeholder:text-slate-500"
                    />
                  </div>
                )}
              </div>

              {/* AI & Language Selectors */}
               <div className="flex flex-col gap-2 w-full lg:w-auto">
                  <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1 lg:text-right">Configuración IA</span>
                  <div className="flex flex-col sm:flex-row gap-3 lg:ml-auto">
                    <ModelSelector 
                        selectedModel={selectedModel}
                        onChange={setSelectedModel}
                        disabled={isLoading}
                    />
                    <LanguageSelector 
                        selectedLanguage={selectedLanguage}
                        onChange={setSelectedLanguage}
                        disabled={isLoading}
                    />
                  </div>
               </div>
            </div>

            <div className="h-px w-full bg-gradient-to-r from-transparent via-gray-200 dark:via-slate-700 to-transparent my-6"></div>

            {/* Tones & Action Row */}
            <div className="flex flex-col xl:flex-row items-end justify-between gap-6">
              <div className="flex flex-col gap-2 w-full xl:w-auto">
                <span className="text-[11px] font-bold text-gray-400 dark:text-slate-300 uppercase tracking-widest ml-1 text-center xl:text-left">Tonos Emocionales</span>
                <div className="flex flex-wrap justify-center xl:justify-start gap-2">
                  {Object.values(ToneOption).map((tone) => (
                    <OptionButton
                      key={tone}
                      option={tone}
                      isSelected={selectedTones.includes(tone)}
                      onClick={() => toggleTone(tone)}
                      disabled={isLoading}
                    />
                  ))}
                </div>
              </div>

              {/* Actions Right Side */}
              <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto justify-end mt-4 xl:mt-0">

                {/* Perspective & Closing Final Wrapper */}
                <div className="flex items-center gap-3">
                    <PerspectiveSelector
                        selectedPerspective={selectedPerspective}
                        onChange={setSelectedPerspective}
                        disabled={isLoading}
                    />

                    {/* Closing Final Toggle */}
                    <button
                        onClick={() => setIsClosingFinal(!isClosingFinal)}
                        disabled={isLoading}
                        title="Activar para incluir mensaje de cierre con encuesta o despedida definitiva"
                        className={`
                            relative flex items-center justify-center gap-1.5 px-4 py-2 rounded-full text-xs font-semibold transition-all duration-200 border
                            ${isClosingFinal 
                                ? 'bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-300 border-red-200 dark:border-red-700 shadow-sm' 
                                : 'bg-gray-100/80 dark:bg-slate-900/80 text-gray-500 dark:text-slate-400 border-gray-200/50 dark:border-slate-800 hover:text-gray-700 dark:hover:text-slate-200'
                            }
                            ${isLoading ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
                        `}
                    >
                        <Flag className={`w-3.5 h-3.5 ${isClosingFinal ? 'fill-current' : ''}`} />
                        <span>Cierre Final</span>
                    </button>
                </div>

                <button
                  onClick={handleTransform}
                  disabled={isLoading || !inputText.trim()}
                  className={`
                    group relative w-full sm:w-auto px-8 py-3 rounded-xl flex items-center justify-center gap-2.5
                    font-bold text-white transition-all duration-300 shadow-xl shadow-indigo-500/20
                    overflow-hidden
                    ${isLoading || !inputText.trim() 
                      ? 'bg-slate-400 dark:bg-slate-600 cursor-not-allowed opacity-70 shadow-none' 
                      : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:scale-[1.02] active:scale-[0.98] hover:shadow-indigo-500/40'}
                  `}
                >
                  {/* Sheen effect */}
                  {!isLoading && inputText.trim() && (
                    <div className="absolute inset-0 -translate-x-full group-hover:translate-x-full transition-transform duration-700 bg-gradient-to-r from-transparent via-white/20 to-transparent skew-x-12"></div>
                  )}

                  {isLoading ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  ) : (
                    <Sparkles className="w-5 h-5" />
                  )}
                  <span className="relative">{isLoading ? 'Procesando...' : 'Transformar'}</span>
                  {!isLoading && <ArrowRight className="w-4 h-4 opacity-80 relative group-hover:translate-x-1 transition-transform" />}
                </button>
              </div>
            </div>
          </div>

          {/* Main Interface Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-[550px] lg:h-[650px]">

            {/* Input Section */}
            <div className="flex flex-col h-full bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm rounded-2xl shadow-sm border border-white/20 dark:border-slate-700 overflow-hidden focus-within:ring-2 focus-within:ring-indigo-500/20 dark:focus-within:ring-indigo-500/40 transition-all duration-300 hover:bg-white/70 dark:hover:bg-slate-800/70">
              <div className="flex items-center justify-between px-5 py-3 border-b border-gray-100/50 dark:border-slate-700/50">
                <label htmlFor="input-text" className="text-xs font-bold text-gray-500 dark:text-slate-300 uppercase tracking-wider flex items-center gap-2">
                  <MessageSquareText className="w-4 h-4" />
                  Entrada
                </label>
                <button 
                  onClick={handleClear}
                  className="text-xs font-medium text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors px-2 py-1 rounded-md hover:bg-red-50 dark:hover:bg-red-900/20"
                  disabled={!inputText}
                >
                  <Eraser className="w-3.5 h-3.5" />
                  Borrar
                </button>
              </div>
              <textarea
                id="input-text"
                className="flex-1 w-full p-6 resize-none focus:outline-none text-[15px] sm:text-base text-slate-700 dark:text-slate-100 placeholder:text-slate-400/70 dark:placeholder:text-slate-500 bg-transparent leading-relaxed"
                placeholder="Escribe o pega el cuerpo de tu respuesta aquí..."
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                disabled={isLoading}
              />
               <div className="px-4 py-2 border-t border-gray-100/50 dark:border-slate-700/50 flex justify-end">
                  <span className="text-[10px] font-medium text-gray-400 dark:text-slate-500 bg-gray-100 dark:bg-slate-800 px-2 py-0.5 rounded-md">
                    {inputText.length} chars
                  </span>
               </div>
            </div>

            {/* Output Section */}
            <div className="h-full">
              <OutputSection 
                originalText={inputText}
                transformedText={outputText}
                correctionSuggestion={correctionSuggestion}
                isLoading={isLoading}
                onRetry={handleTransform}
                onRefine={handleRefine}
                onUpdateText={setOutputText}
                onCheckGrammar={handleCheckGrammar}
                onApplyCorrection={handleApplyCorrection}
                onDiscardCorrection={handleDiscardCorrection}
              />
            </div>
          </div>

          {error && (
            <div className="bg-red-50/90 dark:bg-red-900/20 backdrop-blur text-red-600 dark:text-red-300 px-4 py-3 rounded-xl text-center border border-red-100 dark:border-red-900/30 text-sm animate-fade-in shadow-lg shadow-red-500/5">
              {error}
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { X, Globe } from 'lucide-react';
import { InfoLanguage, GUIDE_CONTENT, DISCLAIMER_CONTENT } from '../content/infoContent';

interface InfoModalProps {
  isOpen: boolean;
  onClose: () => void;
  type: 'GUIDE' | 'DISCLAIMER';
  forced?: boolean; // New prop for mandatory acceptance
}

export const InfoModal: React.FC<InfoModalProps> = ({ isOpen, onClose, type, forced = false }) => {
  const [language, setLanguage] = useState<InfoLanguage>('ES');

  if (!isOpen) return null;

  const contentSource = type === 'GUIDE' ? GUIDE_CONTENT : DISCLAIMER_CONTENT;
