           Guía de Uso
        </button>
        <button onClick={() => setIsDisclaimerOpen(true)} className="w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
           <ShieldAlert className="w-4 h-4" />
           Disclaimer
        </button>
      </nav>

      <div className="p-4 border-t border-slate-200 dark:border-slate-800">
         <button
            onClick={() => setIsDarkMode(!isDarkMode)}
