      <InfoModal isOpen={isGuideOpen} onClose={() => setIsGuideOpen(false)} type="GUIDE" />
      <InfoModal isOpen={isDisclaimerOpen} onClose={handleCloseDisclaimer} type="DISCLAIMER" forced={isForcedDisclaimer} />

      {/* Mobile Overlay */}
      {isMobileMenuOpen && (
        <div 
            className="fixed inset-0 bg-black/50 z-30 lg:hidden backdrop-blur-sm"
            onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      {/* Navigation */}
      <Sidebar />

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 bg-white dark:bg-slate-950/50 relative">
        {/* Background Effects */}
        <div className="absolute inset-0 z-0 pointer-events-none bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-indigo-500/10 via-transparent to-transparent opacity-50"></div>

        {/* Top Header Toolbar */}
        <header className="h-16 flex items-center justify-between px-4 sm:px-6 border-b border-slate-200 dark:border-slate-800 bg-white/80 dark:bg-slate-950/80 backdrop-blur-md z-20 relative">
           <div className="flex items-center gap-3 lg:hidden">
              <button onClick={() => setIsMobileMenuOpen(true)} className="p-2 -ml-2 text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200">
                  <Menu className="w-6 h-6" />
              </button>
              <Logo className="w-8 h-8 text-indigo-500" />
           </div>

           <div className="flex items-center gap-2 ml-auto">
              <ModelSelector selectedModel={selectedModel} onChange={setSelectedModel} disabled={isLoading} />
              <div className="h-4 w-px bg-slate-300 dark:bg-slate-700 mx-2 hidden sm:block"></div>
              <LanguageSelector selectedLanguage={selectedLanguage} onChange={setSelectedLanguage} disabled={isLoading} />
           </div>
        </header>

        {/* Content Body */}
        <div className="flex-1 overflow-hidden relative z-10 flex flex-col">
            {activeTab === 'transform' ? (
                <>
                  <div className="flex-1 overflow-hidden flex flex-col lg:flex-row">
                      {/* Left: Input Pane */}
                      <div className="flex-1 flex flex-col min-h-[300px] border-b lg:border-b-0 lg:border-r border-slate-200 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30">
                          {/* Input Toolbar */}
                          <div className="px-4 sm:px-6 py-3 border-b border-slate-200/50 dark:border-slate-800/50 flex flex-wrap gap-3 items-center justify-between">
                              <label className="text-xs font-bold text-indigo-500 uppercase tracking-widest flex items-center gap-2">
                                  <MessageSquareText className="w-4 h-4" />
