                                  disabled={isLoading}
                              />
                              <div className="absolute bottom-2 right-4 text-[10px] text-slate-400 font-mono">
                                  {inputText.length} chars
                              </div>
                          </div>

                          {/* Input Context Controls */}
                          <div className="p-4 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 space-y-3">
                              <div className="flex flex-col gap-1">
                                  <span className="text-[10px] font-bold text-slate-400 uppercase">Estructura & Tema</span>
                                  <div className="flex flex-col sm:flex-row gap-2">
                                    <div className="flex-1">
                                      <MacroSelector selectedMacro={selectedMacro} onChange={setSelectedMacro} disabled={isLoading} />
                                    </div>
                                    {selectedMacro === MacroType.FIRST && (
                                      <div className="flex-1 flex items-center bg-slate-100 dark:bg-slate-800 rounded-lg px-3 border border-transparent focus-within:border-indigo-500 focus-within:ring-1 focus-within:ring-indigo-500/20 transition-all">
                                          <PenLine className="w-4 h-4 text-slate-400 mr-2" />
                                          <input 
                                            type="text" 
                                            value={issueTopic}
                                            onChange={(e) => setIssueTopic(e.target.value)}
                                            placeholder="Tema (ej: reembolso)"
                                            className="w-full bg-transparent border-none text-sm py-2 focus:ring-0 text-slate-700 dark:text-slate-200 placeholder:text-slate-500"
                                          />
                                      </div>
                                    )}
                                  </div>
                              </div>
                              <div className="flex flex-col gap-1">
                                  <span className="text-[10px] font-bold text-slate-400 uppercase">Longitud</span>
                                  <LengthSelector selectedLength={selectedLength} onChange={setSelectedLength} disabled={isLoading} />
                              </div>
                          </div>
                      </div>

                      {/* Right: Output Pane */}
                      <div className="flex-1 flex flex-col bg-white dark:bg-slate-900/50 min-h-[300px] relative">
                         <OutputSection 
                            originalText={inputText}
                            transformedText={outputText}
                            correctionSuggestion={correctionSuggestion}
                            isLoading={isLoading}
                            onRetry={handleTransform}
                            onRefine={handleRefine}
                            onUpdateText={setOutputText}
                            onCheckGrammar={handleCheckGrammar}
                            onApplyCorrection={handleApplyCorrection}
                            onDiscardCorrection={handleDiscardCorrection}
                         />
                         {/* Error Toast */}
                         {error && (
                            <div className="absolute top-4 left-4 right-4 bg-red-500/10 backdrop-blur border border-red-500/20 text-red-600 dark:text-red-400 px-4 py-3 rounded-xl text-sm text-center animate-fade-in z-20">
                                {error}
                            </div>
                         )}
                      </div>
                  </div>

                  {/* Bottom Action Bar */}
                  <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-lg border-t border-slate-200 dark:border-slate-800 p-4 lg:px-8">
                      <div className="max-w-7xl mx-auto flex flex-col xl:flex-row items-center justify-between gap-4">

                          {/* Tones */}
                          <div className="flex flex-col gap-1.5 w-full xl:w-auto items-center xl:items-start">
                              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Tono Emocional</span>
                              <div className="flex flex-wrap justify-center gap-2">
                                  {Object.values(ToneOption).map((tone) => (
                                    <OptionButton
                                        key={tone}
                                        option={tone}
                                        isSelected={selectedTones.includes(tone)}
                                        onClick={() => toggleTone(tone)}
                                        disabled={isLoading}
                                    />
                                  ))}
                              </div>
                          </div>

                          <div className="h-8 w-px bg-slate-200 dark:bg-slate-800 hidden xl:block"></div>

                          {/* Action Group */}
                          <div className="flex flex-col sm:flex-row items-center gap-4 w-full xl:w-auto justify-end">
                              <div className="flex items-center gap-3">
                                  <PerspectiveSelector selectedPerspective={selectedPerspective} onChange={setSelectedPerspective} disabled={isLoading} />

                                  <button
                                      onClick={() => setIsClosingFinal(!isClosingFinal)}
                                      disabled={isLoading}
                                      className={`
                                          flex items-center gap-2 px-3 py-2 rounded-lg text-xs font-semibold border transition-all
                                          ${isClosingFinal 
                                              ? 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border-red-200 dark:border-red-800' 
                                              : 'bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border-slate-200 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600'
                                          }
                                      `}
                                  >
                                      <Flag className={`w-3.5 h-3.5 ${isClosingFinal ? 'fill-current' : ''}`} />
                                      <span className="hidden sm:inline">Cierre Final</span>
                                  </button>
                              </div>

                              <button
                                  onClick={handleTransform}
                                  disabled={isLoading || !inputText.trim()}
                                  className={`
                                      group relative h-11 px-6 rounded-xl flex items-center justify-center gap-2.5
                                      font-bold text-white shadow-lg transition-all duration-300 w-full sm:w-auto min-w-[160px]
                                      ${isLoading || !inputText.trim() 
                                          ? 'bg-slate-300 dark:bg-slate-700 cursor-not-allowed shadow-none' 
                                          : 'bg-indigo-600 hover:bg-indigo-500 shadow-indigo-500/20 hover:shadow-indigo-500/40 hover:-translate-y-0.5'
                                      }
                                  `}
                              >
                                  {isLoading ? (
                                      <>
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                        <span>Procesando...</span>
                                      </>
                                  ) : (
                                      <>
                                        <Sparkles className="w-4 h-4" />
                                        <span>Transformar</span>
                                        <ChevronRight className="w-4 h-4 opacity-50 group-hover:translate-x-1 transition-transform" />
